 login(){const u=S.users.find(x=>x.email.toLowerCase()===lf.email.trim().toLowerCase()&&x.pw===lf.pw);if(!u)return toast("That email and password don't match an account.");S.session=u.id;save();lf={email:"",pw:""};go("dash")},
