  const lg=f.login&&f.login.on&&can("users")?f.login:null;let loginId="";if(lg){loginId=String(lg.id||"").trim()||clinicUsername(f.name);if(!/@/.test(loginId)&&!/^[a-z0-9][a-z0-9._-]{2,39}$/i.test(loginId))return toast("Usernames are 3-40 characters: letters, numbers, dots, dashes or underscores.");if(/@/.test(loginId)&&!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(loginId))return toast("Enter a valid email address for the login.")}
