 startCorrect:e=>{rej={id:e.dataset.id,reason:""};modal("Correct released results",`<p class="small">The order goes back to testing so results can be changed. When it's released again, the report is marked <b>CORRECTED</b>, shows the reason, and the provider is alerted again. The original release stays in the audit log.</p><div class="field" style="margin-top:12px"><label class="req">Reason for correction</label><textarea class="input" data-b="rej.reason" placeholder="e.g. Transcription error in THC-COOH result"></textarea></div>`,{foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn primary" data-a="confirmCorrect">Reopen for correction</button>`})},
 confirmCorrect(){const reason=String((rej&&rej.reason)||"").trim();if(!reason)return toast("Enter the reason for the correction.");const o=orderOf(rej.id),c=clinicOf(o.clinicId),p=patientOf(o.patientId);
  o.corrections=[...(o.corrections||[]),{at:Date.now(),by:me().name,reason,prevReleasedAt:o.releasedAt}];o.status="In Process";delete o.verified;o.history.push({s:"In Process",at:Date.now(),by:me().name,note:`Reopened for correction: ${reason}`});
  pushNote(c.id,o.id,"Results being corrected",`${o.accession} for ${p.first} ${p.last[0]}. is being corrected. A corrected report will follow.`,"info");save();closeModal();resEdit=null;go("entry",{id:o.id});toast("Reopened for correction")},
 changePw(){lf.pw1="";lf.pw2="";modal("Change password",`<div class="grid"><div class="field"><label>New password</label><input class="input" type="password" autocomplete="new-password" data-b="lf.pw1"><span class="hint">At least 12 characters.</span></div><div class="field"><label>Confirm new password</label><input class="input" type="password" autocomplete="new-password" data-b="lf.pw2" data-enter="saveMyPw"></div></div>`,{foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn primary" data-a="saveMyPw">Save password</button>`})},
