 supUrg:e=>{spf.urgency=e.dataset.val;render()},
 supSubmit(){const f=spf,cat=supplyItems(),items=cat.map(x=>({name:supplyLabel(x),qty:parseInt(f.qty[x.id],10)||0,max:parseInt(x.max,10)||0})).filter(x=>x.qty>0);
  if(!items.length)return toast("Enter a quantity for at least one item.");const over=items.find(x=>x.max&&x.qty>x.max);if(over)return toast(`${over.name}: the most you can order at once is ${over.max}. Call the lab for larger quantities.`);items.forEach(x=>delete x.max);if(!f.recipient.trim()||!f.address.trim()||!f.city.trim()||!f.state.trim()||!f.zip.trim())return toast("Complete the recipient and ship-to address.");
  const c=myClinic(),x={id:uid("s"),number:"SUP-"+ymd(Date.now()).slice(2)+"-"+rid(),clinicId:c.id,items,shipTo:{recipient:f.recipient.trim(),phone:f.phone.trim(),address:f.address.trim(),city:f.city.trim(),state:f.state.trim(),zip:f.zip.trim()},urgency:f.urgency,notes:f.notes.trim(),status:"New",createdAt:Date.now(),by:me().name};
  S.supply_orders.push(x);pushNote("lab",null,f.urgency==="STAT"?"New STAT supply order":"New supply order",`${c.name} ordered supplies (${x.number}).`,f.urgency==="STAT"?"crit":"info");save();spf=null;render();toast("Supply order submitted")},
 supShip:e=>{const x=S.supply_orders.find(y=>y.id===e.dataset.id);rej={sup:x.id,carrier:x.carrier||"UPS",tracking:x.tracking||"",edit:x.status==="Shipped"};
  modal(rej.edit?`Tracking for ${x.number}`:`Ship ${x.number}`,`<p class="small">${esc((clinicOf(x.clinicId)||{}).name||"")} · ${x.items.map(i=>`${i.qty} × ${esc(i.name)}`).join(", ")}</p><div class="grid g2" style="margin-top:12px"><div class="field"><label>Carrier</label><select class="input" data-b="rej.carrier">${["UPS","FedEx","USPS","DHL","Courier","Other"].map(c=>`<option ${rej.carrier===c?"selected":""}>${c}</option>`).join("")}</select></div><div class="field"><label>Tracking number</label><input class="input" data-b="rej.tracking" value="${esc(rej.tracking)}" placeholder="Scan or type"></div></div><p class="xs muted" style="margin-top:8px">The clinic sees the tracking number and a link to the carrier on their Supplies page.</p>`,{foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn primary" data-a="supShipSave">${rej.edit?"Save":"Mark shipped"}</button>`})},
 supShipSave(){const x=S.supply_orders.find(y=>y.id===rej.sup),tr=String(rej.tracking||"").trim(),first=x.status!=="Shipped";x.carrier=rej.carrier;x.tracking=tr;if(first){x.status="Shipped";x.shippedAt=Date.now();x.shippedBy=me().name}else{x.trackingUpdatedAt=Date.now();x.trackingUpdatedBy=me().name}
  if(first||tr)pushNote(x.clinicId,null,first?"Supplies shipped":"Supply tracking updated",`${x.number} ${first?"has shipped":"tracking"}${tr?`: ${x.carrier} ${tr}`:""}.`,"ok");save();closeModal();render();toast(first?"Marked shipped":"Tracking saved")},
