 qcHoldSave(){const o=S.orders.find(x=>x.id===rej.hold),note=String(rej.note||"").trim();if(!note)return toast("Describe what was done.");o.qcHold.cleared={...signer(),action:rej.action,note};o.history.push({s:o.status,at:Date.now(),by:me().name,note:`QC hold released: ${rej.action}. ${note}`});save();closeModal();render();toast("QC hold released")},
