 qmsOpen:e=>{go("qmsd",{id:e.dataset.id})},
 qmsNew:e=>{const k=e.dataset.kind,K=QK[k];qmf={kind:k,ref:e.dataset.ref||null};K.f.forEach(([f,,type,,opts])=>{if(type==="select"&&opts&&["status","active","outcome","result"].includes(f))qmf[f]=opts[0]==="Quarantine"?"In use":opts[0]});
  if(k==="capa")qmf.status="Open";if(k==="sop")qmf.status="Active";if(k==="equipment")qmf.status="In service";if(k==="personnel")qmf.active="Active";if(["maintenance","temp"].includes(k))qmf.at=new Date().toISOString();if(["training","competency","access","risk","capa"].includes(k))qmf.at=ymd(Date.now(),"-");
  if(["access","risk"].includes(k))qmf.by=me().name;if(k==="competency")qmf.assessor=me().name;openForm=null;qFormModal()},
 qmsEdit:e=>{const r=QM.recs.find(x=>x.id===e.dataset.id);if(!r)return;qmf=JSON.parse(JSON.stringify(r));qFormModal()},
 async qmsSave(){const f=qmf,K=QK[f.kind];const miss=K.f.filter(([k,,type,req])=>req&&type!=="check"&&!String(f[k]??"").trim()).map(x=>x[1]);if(miss.length)return toast(`Fill in: ${miss.join(", ")}`);
  if(f.kind==="temp"){const eq=QM.recs.find(x=>x.id===f.ref);if(eq&&(+f.reading<+eq.tempMin||+f.reading>+eq.tempMax)&&!String(f.notes||"").trim())return toast("This reading is out of range. Record the corrective action in Notes.")}
  if(f.kind==="pt"&&f.outcome==="Unsatisfactory"&&!String(f.action||"").trim())return toast("Record the investigation and corrective action for an unsatisfactory result.");
  if(f.kind==="sop"&&f.id){const old=QM.recs.find(x=>x.id===f.id);if(old&&old.version!==f.version)toast("New version: staff will be asked to acknowledge it.")}
  const rec={...f,id:f.id||(f.kind+Date.now().toString(36)+rid()),by:f.by||me().name,updatedBy:me().name,updatedAt:Date.now()};if(["maintenance","temp"].includes(rec.kind))rec.at=rec.at?new Date(qdate(rec.at)).toISOString():new Date().toISOString();
  try{await DB.qmsSave(rec);const i=QM.recs.findIndex(x=>x.id===rec.id);if(i>=0)QM.recs[i]=rec;else QM.recs.push(rec);closeModal();render();toast("Saved")}catch(err){toast(errMsg(err))}},
