 sgStore:e=>storeModal(orderOf(e.dataset.id)),
 sgSave(){const f=stf;if(!String(f.unit).trim())return toast("Enter where the specimen is stored.");if(!f.retainUntil)return toast("Enter how long to keep it.");const o=orderOf(f.id),moved=!!o.storage;
  o.storage={unit:String(f.unit).trim(),rack:String(f.rack||"").trim(),position:String(f.position||"").trim(),retainUntil:new Date(f.retainUntil+"T23:59").getTime(),storedAt:Date.now(),storedBy:me().name};
  o.history.push({s:o.status,at:Date.now(),by:me().name,note:`${moved?"Specimen moved to":"Specimen stored in"} ${o.storage.unit}${o.storage.rack?` / ${o.storage.rack}`:""}${o.storage.position?` / ${o.storage.position}`:""}, keep until ${fmtD(o.storage.retainUntil)}`});save();closeModal();render();toast(moved?"Location updated":"Specimen stored")},
 sgDispose(){const ids=Object.keys(SG.sel).filter(k=>SG.sel[k]);if(!ids.length)return toast("Select specimens to record.");rej={ids,method:"Biohazard waste",at:ymd(Date.now(),"-")};
  modal("Record disposal",`<p class="small">${ids.length} specimen${ids.length>1?"s":""} will be marked discarded. The orders and results are kept.</p><div class="grid g2" style="margin-top:12px"><div class="field"><label>Method</label><select class="input" data-b="rej.method">${["Biohazard waste","Returned to client","Sent to reference lab","Other"].map(m=>`<option>${m}</option>`).join("")}</select></div><div class="field"><label>Date</label><input class="input" type="date" data-b="rej.at" value="${rej.at}"></div></div>`,{foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn danger" data-a="sgDisposeConfirm">Record disposal</button>`})},
