 releaseSigned(){const o=S.orders.find(x=>x.id===route.p.id);const sig=ui.esigOk&&ui.esigOk.orderId===o.id?ui.esigOk:null;ui.esigOk=null;if(!sig)return toast("Sign to release.");let rvNote="";if(can("results.enter")){const r={...resEdit};delete r._id;if(!o.verified){rvNote=confirmReview(o,r,"release");if(rvNote===false)return}if(JSON.stringify(r)!==JSON.stringify(o.results||{}))delete o.verified;o.results=r}else if(!o.verified)return toast("A scientist must verify these results first.");const add=reflexCheck(o);if(add.length){save();resEdit=null;render();return toast(`Positive screen: ${add.length} definitive test${add.length>1?"s":""} added. Run them on the SCIEX before releasing.`)}if(rvNote)o.history.push({s:o.status,at:Date.now(),by:me().name,note:rvNote});const selfApproved=!o.verified;if(selfApproved){o.verified={...signer(),atRelease:true}}if(!releaseOrder(o,sig)){if(rvNote)o.history.pop();if(selfApproved)delete o.verified;return}resEdit=null;go("order",{id:o.id});toast(o.flags.crit?"Released. Critical call task created.":"Released. Sending provider alerts…");sendAlertsNow(false)},
