function addrLines(a){a=String(a||"").trim();const m=a.match(/^(.*),\s*([^,]+),\s*([A-Za-z]{2})\s+(\d{5}(?:-\d{4})?)$/);return m?[m[1].trim(),`${m[2].trim()}, ${m[3].toUpperCase()} ${m[4]}`]:a?[a]:[]}
// Approver ID: the person's initials + the first 4 characters of their account ID. Stable, unique per account, shown on the Users page.
function staffCode(name,uid){const ini=String(name||"").replace(/^dr\.?\s+/i,"").split(/\s+/).filter(Boolean).map(w=>w[0]).join("").toUpperCase().replace(/[^A-Z]/g,"").slice(0,3)||"XX";return `${ini}-${String(uid||"").replace(/[^A-Za-z0-9]/g,"").slice(0,4).toUpperCase()||"0000"}`}
const signer=()=>{const u=me();return {by:u.name,uid:u.id,code:staffCode(u.name,u.id),at:Date.now()}};
const signerText=x=>x?`${x.by}${x.code?` (ID ${x.code})`:""}, ${fmtDT(x.at)}`:"";
const ymd=(t,sep="")=>{const d=new Date(t);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join(sep)};
const norm=s=>String(s||"").toLowerCase().replace(/[^a-z0-9]/g,"");
const fmtN=v=>v>=100?Math.round(v).toLocaleString("en-US"):String(Math.round(v*10)/10);
