const inLab=o=>["Received","In Process"].includes(o.status)
// Manual result entry applies the same rules as an instrument import, and records who typed it.
function manualMark(r){r.src="manual";r.by=me()?me().name:"";r.at=Date.now()}
function manualDerive(o,code,a,r,field){manualMark(r);
 if(field==="c"&&a.type!=="conf"&&a.type!=="quant"&&a.cutoff){const num=parseFloat(String(r.c).replace(/,/g,""));if(isFinite(num))r.v=num>=parseFloat(a.cutoff)?"Positive":"Negative";else if(/^pos/i.test(r.c))r.v="Positive";else if(/^neg/i.test(r.c))r.v="Negative"}
 if(code==="UDS"&&[VALIDITY.cr,VALIDITY.sg,VALIDITY.ph].includes(a.name)){const R=resEdit.UDS,num=k=>{const x=parseFloat((R[k]||{}).v);return isNaN(x)?undefined:x};const cr=num(VALIDITY.cr),sg=num(VALIDITY.sg),ph=num(VALIDITY.ph);
  if([cr,sg,ph].some(x=>x!==undefined))R[VALIDITY.out]={v:validityOf(cr,sg,ph),src:"calculated"}}}
function manualConc(o,code,a,r,ki,val){const comps=(S.confMap[specOf(o)]||{})[a.name]||[],c=comps[ki];if(!c)return;manualMark(r);r.raw=r.raw||{};
 const t=String(val??"").replace(/,/g,"").trim();if(t==="")delete r.raw[c.name];else r.raw[c.name]=t;
 const seen=comps.filter(k=>r.raw[k.name]!==undefined&&isFinite(parseFloat(r.raw[k.name])));
 if(!seen.length){delete r.comps;return}
 const det={};seen.forEach(k=>{const x=parseFloat(r.raw[k.name]),u=parseFloat(k.uloq),pp=x>=parseFloat(k.cutoff);det[canon(k.name)]={pos:pp,text:pp?(u&&x>u?`>${fmtN(u)}`:fmtN(x)):"",issues:[]}});
 const pos=seen.filter(k=>det[canon(k.name)].pos);r.v=pos.length?"Positive":"Negative";r.c=pos.map(k=>`${k.name} ${det[canon(k.name)].text}`).join("; ");r.comps=det}
// Remember which instrument run produced an order's results, so verification can check that run's QC was approved.
const dayKey=t=>{const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`};
function noteRun(o,inst,at){const t=at||Date.now();o.runs=(o.runs||[]).filter(r=>!(r.inst===inst&&r.day===dayKey(t)));o.runs.push({inst,at:t,day:dayKey(t),by:me()?me().name:""})}
// Plain-language reason a sample ID in an instrument file couldn't be posted to an order.
function whyUnmatched(sid,o,needLabel){if(!o)return "no open order with this accession number (check the number, or whether it was already released)";
 if(!inLab(o))return ["Released","Amended","Corrected"].includes(o.status)?`order ${o.accession} is already released`:["Rejected","Cancelled"].includes(o.status)?`order ${o.accession} is ${o.status.toLowerCase()}`:`order ${o.accession} hasn't been received yet (status ${o.status})`;
 return `order ${o.accession} doesn't include ${needLabel}`};
const complete=(o,code)=>analytesFor(o,T(code)).every(a=>{if(a.type==="calc")return true;const r=(o.results[code]||{})[a.name];return r&&r.v!==""&&r.v!=null});
const pendingFor=code=>S.orders.filter(o=>o.tests.includes(code)&&inLab(o)&&!complete(o,code));
