const refPending=()=>S.orders.filter(o=>inLab(o)&&refTests(o).length&&!o.sendout);
/* Amico DX electronic referrals: per-order destination, HL7 ORM^O01 out, status back from the connector */
const AMICO_DEFAULT={on:false,name:"Amico DX",clia:"45D2301329",facility:"AMICODX",app:"ICARUS",email:"",tests:["WOUND","NAIL","UTIABR","UTI"],ins:false};
