/* ---------- offline order entry (mobile collectors) ---------- */
const offlineAllowed=()=>isLab()&&can("orders.enter")&&Offline.supported();
let offPersistTimer=null;
function offlinePersist(){clearTimeout(offPersistTimer);offPersistTimer=setTimeout(()=>{Offline.saveQueue(S.session,{patients:S.patients,orders:S.orders,notes:S.notes}).catch(e=>toast("Couldn't save on this device: "+errMsg(e)))},150)}
async function tryOffline(){try{if(!Offline.supported()||!Offline.deviceEnabled()||!Offline.hasStoredSession())return false;const ref=await Offline.loadRef();if(!ref||Date.now()-ref.savedAt>7*DAY)return false;
 const q=(await Offline.loadQueue(ref.profile.user_id))||{};
 S={...emptyS(),clinics:ref.clinics||[],lab:ref.lab||S.lab,confMap:ref.confMap||S.confMap,fees:ref.fees||S.fees,patients:q.patients||[],orders:q.orders||[],notes:q.notes||[],offline:true,theme:localStorage.getItem("fbg-theme"),session:ref.profile.user_id,
  users:[{id:ref.profile.user_id,email:ref.profile.email,name:ref.profile.name||ref.profile.email,role:"lab",clinicId:null,roles:ref.profile.lab_roles||[]}]};
 try{migrate()}catch(e){}applyTheme();lastActive=Date.now();route={v:"offline",p:{}};render();return true}catch(e){return false}}
async function offlineAfterOnline(){if(!offlineAllowed()||!Offline.deviceEnabled())return;const u=me();
 try{await Offline.saveRef({profile:{user_id:u.id,email:u.email,name:u.name,lab_roles:u.roles},clinics:S.clinics,lab:S.lab,confMap:S.confMap,fees:S.fees});
  const have=(await Offline.seqs()).length;if(have<10){const add=[];for(let i=have;i<15;i++){try{add.push(await DB.nextSeq("accession"))}catch(e){break}}if(add.length)await Offline.addSeqs(add)}
  const q=await Offline.loadQueue(u.id);if(!q||!((q.orders||[]).length||(q.patients||[]).length))return;
  const nn=x=>String(x||"").trim().toLowerCase().replace(/[^a-z]/g,""),pmap={};
  (q.patients||[]).forEach(p=>{if(S.patients.some(x=>x.id===p.id))return;const dup=S.patients.find(x=>!x.mergedInto&&x.clinicId===p.clinicId&&x.dob===p.dob&&nn(x.last)===nn(p.last)&&nn(x.first)===nn(p.first));if(dup)pmap[p.id]=dup.id;else S.patients.push(p)});
  let n=0;(q.orders||[]).forEach(o=>{if(S.orders.some(x=>x.id===o.id))return;if(pmap[o.patientId])o.patientId=pmap[o.patientId];o.history=[...(o.history||[]),{s:o.status,at:Date.now(),by:u.name,note:"Uploaded from offline entry on a collector device"}];S.orders.push(o);n++});
  (q.notes||[]).forEach(x=>{if(!S.notes.some(y=>y.id===x.id))S.notes.push(x)});
  await DB.flushNow(S,true);if(!DB.hasUnsaved(S,true)){await Offline.clearQueue(u.id);if(n)toast(`${n} order${n>1?"s":""} entered offline uploaded`)}else toast("Some offline orders haven't uploaded yet. They'll try again.");render()}catch(e){}}
function vOffline(){const os=[...S.orders].sort((a,b)=>b.createdAt-a.createdAt);
 return `<div class="page-h"><div><h1>Offline orders</h1><p class="muted">Saved on this device, encrypted. They upload automatically when you're back online.</p></div><div class="row"><button class="btn" data-a="offlineRetry">Check connection</button><button class="btn primary" data-a="go" data-v="order-new">${I.plus} New order</button></div></div>
 <div class="panel">${os.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Accession</th><th>Patient</th><th>Clinic</th><th>Tests</th><th>Collected</th><th></th></tr></thead><tbody>${os.map(o=>`<tr><td class="acc small">${o.accession}</td><td class="small nm">${esc(pname(patientOf(o.patientId)))}</td><td class="small">${esc((clinicOf(o.clinicId)||{}).name||"")}</td><td class="small">${o.tests.map(c=>`<span class="tag">${c}</span>`).join("")}</td><td class="small">${fmtDT(o.collectedAt)}</td><td style="text-align:right;white-space:nowrap"><button class="btn sm" data-a="printLabels" data-id="${o.id}">${I.print} Labels</button> <button class="btn sm ghost" data-a="req" data-id="${o.id}">Requisition</button></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty"><h3>Nothing waiting to upload</h3><p>Orders you enter while offline appear here.</p></div>`}</div>`}

/* ---------- ICD-10-CM code search (CMS April 2026 release, billable codes only) ---------- */
const ICDX={list:null,map:null,loading:null,err:""};
function icdLoad(){if(ICDX.list||ICDX.loading)return ICDX.loading;if(typeof fetch!=="function")return null;ICDX.loading=fetch("/icd10cm-2026.json").then(r=>{if(!r.ok)throw new Error("ICD-10 list unavailable");return r.json()}).then(l=>{ICDX.list=l.map(([c,d])=>({c,d,k:c.replace(".","").toLowerCase(),w:d.toLowerCase()}));ICDX.map=new Map(l.map(([c,d])=>[c,d]));render()}).catch(e=>{ICDX.err=errMsg(e);ICDX.loading=null});return ICDX.loading}
const icdDesc=c=>{if(!ICDX.map){icdLoad();return ""}return ICDX.map.get(String(c).toUpperCase())||""};
const icdBillable=c=>ICDX.map?ICDX.map.has(String(c).toUpperCase()):null;
function icdSearch(q,limit=15){if(!ICDX.list){icdLoad();return null}q=String(q||"").trim().toLowerCase();if(q.length<2)return [];
 const code=q.replace(".","");if(/^[a-z]\d/.test(code)){return ICDX.list.filter(x=>x.k.startsWith(code)).slice(0,limit)}
 const toks=q.split(/\s+/).filter(Boolean),out=[];for(const x of ICDX.list){let ok=true,score=0;for(const t of toks){const i=x.w.indexOf(t);if(i<0){ok=false;break}if(i===0||x.w[i-1]===" "||x.w[i-1]==="(")score+=2;else score+=1}if(ok)out.push([score*1000-x.d.length,x])}
 return out.sort((a,b)=>b[0]-a[0]).slice(0,limit).map(x=>x[1])}

/* ---------- order facts (reports, quality indicators) ---------- */
// Compact rows from the server covering the whole period, shaped like orders so the report code works on either.
const FX={key:"",rows:null,claims:null,busy:false};
function factsFor(fromMs,clinic){const key=`${Math.floor(fromMs/DAY)}|${clinic||""}`;if(!DB.scaled()||S.offline)return null;
 if(FX.key!==key&&!FX.busy){FX.busy=true;FX.key=key;FX.rows=null;Promise.all([DB.orderFacts(fromMs,clinic),can("billing.view")||can("*")?DB.claimsSince(fromMs):Promise.resolve(null)]).then(([rows,cl])=>{FX.rows=(rows||[]).map(r=>({id:r.id,clinicId:r.clinic_id,patientId:r.patient_id,createdAt:new Date(r.created_at).getTime(),status:r.status,tests:r.tests||[],billType:r.bill_type,collectedAt:+r.collected_at||0,releasedAt:r.released_at?+r.released_at:null,rejectReason:r.reject_reason,corrections:Array(r.corrections||0).fill({}),summary:r.summary,history:r.received_at?[{s:"Received",at:+r.received_at}]:[],_fact:true}));FX.claims=cl;FX.busy=false;render()}).catch(()=>{FX.busy=false;FX.key=""})}
 return FX.key===key?FX.rows:null}
const factClaims=()=>FX.claims||S.claims||[];

/* ---------- management reports ---------- */
const RP={months:6,clinic:""};
const AN={from:"",to:"",clinic:"",test:""};
function analyticsData(){const today=ymd(Date.now(),"-");if(!AN.to)AN.to=today;if(!AN.from)AN.from=ymd(Date.now()-89*DAY,"-");
 const lab=isLab(),from=Date.parse(AN.from+"T00:00:00"),to=Date.parse(AN.to+"T23:59:59.999"),clinic=lab?AN.clinic:me().clinicId;
 const fx=lab?factsFor(from,clinic):null,src=fx||S.orders;
 const os=src.filter(o=>o.createdAt>=from&&o.createdAt<=to&&(!clinic||o.clinicId===clinic)&&(!AN.test||o.tests.includes(AN.test)));
 const sup=(S.supply_orders||[]).filter(x=>x.createdAt>=from&&x.createdAt<=to&&(!clinic||x.clinicId===clinic));
 return {os,sup,from,to,clinic,loading:lab&&DB.scaled()&&!fx&&!S.offline}}
const recvAt=o=>{const h=(o.history||[]).find(x=>x.s==="Received");return h?h.at:null};
const pctl=(a,p)=>{if(!a.length)return null;const x=[...a].sort((m,n)=>m-n);return x[Math.min(x.length-1,Math.floor(p*(x.length-1)+.5))]};
const durTxt=ms=>ms==null?"—":ms<2*DAY?`${(ms/36e5).toFixed(1)} h`:`${(ms/DAY).toFixed(1)} d`;
function abOfTest(o,code){if(o.summary&&o.summary.ab&&code in o.summary.ab)return o.summary.ab[code];if(o.results){const a=testAbnormal(o);if(a&&code in a)return a[code]}return null}
function analyticsModel(){const {os,sup,from,to,clinic,loading}=analyticsData(),rel=os.filter(o=>o.releasedAt);
 const span=(l,f,t)=>l.map(o=>{const a=f(o),b=t(o);return a&&b&&b>=a?b-a:null}).filter(x=>x!=null);
 const stages=[["Order placed → collected",span(os.filter(o=>o.collectedAt>o.createdAt+6e4),o=>o.createdAt,o=>o.collectedAt)],["Collected → received at lab",span(os,o=>o.collectedAt,recvAt)],["Received → results released",span(rel,recvAt,o=>o.releasedAt)],["Collected → results released (total)",span(rel,o=>o.collectedAt,o=>o.releasedAt)]];
 const shipped=sup.filter(x=>x.status==="Shipped");stages.unshift(["Supply order → shipped",span(shipped,x=>x.createdAt,x=>x.shippedAt)]);
 const byTest={};rel.forEach(o=>o.tests.forEach(code=>{if(AN.test&&code!==AN.test)return;const v=abOfTest(o,code);const r=byTest[code]=byTest[code]||{code,n:0,ab:0,unk:0};if(v==null){r.unk++;return}r.n++;r.ab+=v}));
 const tests=Object.values(byTest).sort((a,b)=>b.n-a.n),totN=tests.reduce((a,t)=>a+t.n,0),totAb=tests.reduce((a,t)=>a+t.ab,0);
 const supBy={};sup.forEach(x=>{const k=x.clinicId,r=supBy[k]=supBy[k]||{clinicId:k,orders:0,shipped:0,items:0,kits:0,byItem:{}};r.orders++;if(x.status==="Shipped"){r.shipped++;x.items.forEach(i=>{const q=+i.qty||0;r.items+=q;if(/kit/i.test(i.name))r.kits+=q;r.byItem[i.name]=(r.byItem[i.name]||0)+q})}});
 return {os,rel,sup,shipped,stages,tests,totN,totAb,supBy:Object.values(supBy).sort((a,b)=>b.items-a.items),from,to,clinic,loading}}
function vAnalytics(){const lab=isLab(),M=analyticsModel(),pc=(a,n)=>n?(a/n*100).toFixed(1)+"%":"—";
 const allTests=[...new Set((lab?S.orders:scopeOrders()).flatMap(o=>o.tests))].filter(c=>T(c)).sort((a,b)=>T(a).name.localeCompare(T(b).name));
 const tbl=(h,rows)=>`<div class="tbl-wrap"><table class="tbl"><thead><tr>${h.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")||`<tr><td colspan="${h.length}" class="small muted">No data in this date range.</td></tr>`}</tbody></table></div>`;
 const bar=(p,tone)=>`<div style="height:8px;border-radius:4px;background:var(--sunken);min-width:90px"><div style="height:8px;border-radius:4px;width:${Math.max(0,Math.min(100,p))}%;background:${tone}"></div></div>`;
 return `<div class="page-h"><div><h1>Analytics</h1><p class="muted">${lab?"Kit volume, turnaround and findings across clinics.":`Kit volume, turnaround and findings for ${esc(myClinic().name)}.`} No patient names.${M.loading?" Loading the full period…":""}</p></div><button class="btn" data-a="anExport">${I.down} Download report (CSV)</button></div>
 <div class="row" style="margin-bottom:16px;gap:10px;flex-wrap:wrap;align-items:flex-end">
  <div class="field" style="margin:0"><label>From</label><input class="input" type="date" data-b="an.from" data-live="1" value="${esc(AN.from)}"></div>
  <div class="field" style="margin:0"><label>To</label><input class="input" type="date" data-b="an.to" data-live="1" value="${esc(AN.to)}"></div>
  ${[["30","Last 30 days"],["90","Last 90 days"],["365","Last 12 months"]].map(([d,l])=>`<span class="pill" data-a="anRange" data-val="${d}">${l}</span>`).join("")}
  ${lab?`<div class="field" style="margin:0"><label>Clinic</label><select class="input" data-b="an.clinic" data-live="1"><option value="">All clinics</option>${S.clinics.map(c=>`<option value="${c.id}" ${AN.clinic===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div>`:""}
  <div class="field" style="margin:0"><label>Test or panel</label><select class="input" data-b="an.test" data-live="1"><option value="">All tests</option>${allTests.map(c=>`<option value="${c}" ${AN.test===c?"selected":""}>${esc(T(c).name)}</option>`).join("")}</select></div></div>
 <div class="stack"><div class="stats"><div class="stat"><div class="v">${M.os.length}</div><div class="k">Orders</div></div><div class="stat"><div class="v">${M.rel.length}</div><div class="k">Resulted</div></div><div class="stat"><div class="v" style="${M.totAb?"color:var(--danger)":""}">${pc(M.totAb,M.totN)}</div><div class="k">Abnormal findings (${M.totAb} of ${M.totN} tests)</div></div><div class="stat"><div class="v">${durTxt(pctl(M.stages[4][1],.5))}</div><div class="k">Median collection to result</div></div><div class="stat"><div class="v">${M.supBy.reduce((a,r)=>a+r.items,0)}</div><div class="k">Supplies shipped (items)</div></div></div>
 <div class="panel"><div class="panel-h"><div><h2>Normal vs abnormal findings</h2><p class="small muted">Resulted tests in the date range. A test counts as abnormal when any of its results is flagged (high, low, positive or critical).</p></div></div>${tbl(["Test or panel","Resulted","Normal","Abnormal","% abnormal",""],[...M.tests.map(t=>{const p=t.n?t.ab/t.n*100:0;return `<tr><td class="small nm">${esc(T(t.code).name)}</td><td class="small">${t.n}${t.unk?`<div class="xs muted">${t.unk} not yet summarized</div>`:""}</td><td class="small">${t.n-t.ab} (${pc(t.n-t.ab,t.n)})</td><td class="small">${t.ab}</td><td class="small"><b>${pc(t.ab,t.n)}</b></td><td>${bar(p,"var(--danger)")}</td></tr>`}),...(M.tests.length>1?[`<tr><td class="small nm">All tests</td><td class="small">${M.totN}</td><td class="small">${M.totN-M.totAb} (${pc(M.totN-M.totAb,M.totN)})</td><td class="small">${M.totAb}</td><td class="small"><b>${pc(M.totAb,M.totN)}</b></td><td>${bar(M.totN?M.totAb/M.totN*100:0,"var(--danger)")}</td></tr>`]:[])])}</div>
 <div class="panel"><div class="panel-h"><div><h2>Turnaround</h2><p class="small muted">Time between each step, for orders placed in the date range.</p></div></div>${tbl(["Step","Count","Median","90th percentile"],M.stages.map(([l,a])=>`<tr><td class="small nm">${l}</td><td class="small">${a.length}</td><td class="small">${durTxt(pctl(a,.5))}</td><td class="small">${durTxt(pctl(a,.9))}</td></tr>`))}</div>
 <div class="panel"><div class="panel-h"><div><h2>Kits and supplies sent</h2><p class="small muted">Shipped supply orders placed in the date range${lab?", by clinic":""}.</p></div></div>${tbl([...(lab?["Clinic"]:[]),"Supply orders","Shipped","Items shipped","Collection kits","Items"],M.supBy.map(r=>`<tr>${lab?`<td class="small nm">${esc((clinicOf(r.clinicId)||{}).name||r.clinicId)}</td>`:""}<td class="small">${r.orders}</td><td class="small">${r.shipped}</td><td class="small">${r.items}</td><td class="small">${r.kits}</td><td class="xs">${Object.entries(r.byItem).sort((a,b)=>b[1]-a[1]).map(([n,q])=>`${q} × ${esc(n)}`).join("<br>")}</td></tr>`))}</div></div>`}
const monthKey=t=>{const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`};
const monthLabel=k=>new Date(k+"-15").toLocaleDateString("en-US",{month:"short",year:"2-digit"});
function orderCharge(o){const cl=factClaims().find(c=>c.orderId===o.id);return cl?claimTotal(cl):0}
function barChart(rows,series,opts={}){const W=900,H=opts.h||260,P={l:46,r:12,t:12,b:34},n=rows.length;if(!n)return `<div class="empty">No data.</div>`;
 const max=Math.max(1,...rows.map(r=>series.reduce((a,s)=>a+(r[s.k]||0),0))),bw=(W-P.l-P.r)/n,y=v=>P.t+(H-P.t-P.b)*(1-v/max);
 const ticks=[0,.25,.5,.75,1].map(f=>Math.round(max*f));
 return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block" role="img" aria-label="${esc(opts.label||"Chart")}">${ticks.map(t=>`<line x1="${P.l}" x2="${W-P.r}" y1="${y(t)}" y2="${y(t)}" stroke="currentColor" opacity=".1"/><text x="${P.l-6}" y="${y(t)+4}" font-size="11" text-anchor="end" fill="currentColor" opacity=".6">${t}</text>`).join("")}
 ${rows.map((r,i)=>{let acc=0;return series.map(s2=>{const v=r[s2.k]||0,y0=y(acc),y1=y(acc+v);acc+=v;return v?`<rect x="${P.l+i*bw+bw*.18}" y="${y1}" width="${bw*.64}" height="${Math.max(0,y0-y1)}" fill="${s2.c}"><title>${esc(r.label)} · ${esc(s2.n)}: ${v}</title></rect>`:""}).join("")+`<text x="${P.l+i*bw+bw/2}" y="${H-12}" font-size="11" text-anchor="middle" fill="currentColor" opacity=".7">${esc(r.label)}</text>`}).join("")}</svg>
 <div class="row" style="gap:14px;flex-wrap:wrap;margin-top:6px">${series.map(s2=>`<span class="xs"><span style="display:inline-block;width:10px;height:10px;border-radius:2px;background:${s2.c};margin-right:5px;vertical-align:-1px"></span>${esc(s2.n)}</span>`).join("")}</div>`}
function reportData(){const start=new Date();start.setDate(1);start.setHours(0,0,0,0);start.setMonth(start.getMonth()-(RP.months-1));
 const fx=factsFor(start.getTime(),RP.clinic),src=fx||S.orders,os=src.filter(o=>o.createdAt>=start.getTime()&&(!RP.clinic||o.clinicId===RP.clinic)),months=[];for(let i=0;i<RP.months;i++){const d=new Date(start);d.setMonth(start.getMonth()+i);months.push(monthKey(d))}
 return {os,months,loading:DB.scaled()&&!fx&&!S.offline}}
function vReports(){const {os,months,loading}=reportData(),money_=can("billing.view")||can("*"),rel=os.filter(o=>o.releasedAt);
 const cats=[["tox","Toxicology","#1590cf"],["blood","Blood","#7c5cd6"],["mol","Molecular","#16a37a"],["other","Other","#9aa6bb"]];
 const catOf=o=>o.tests.some(c=>c==="UDS"||isDef(c))?"tox":o.tests.some(c=>T(c).cat==="blood")?"blood":o.tests.some(c=>T(c).cat==="mol")?"mol":"other";
 const vol=months.map(k=>{const r={label:monthLabel(k)};os.filter(o=>monthKey(o.createdAt)===k).forEach(o=>{const c=catOf(o);r[c]=(r[c]||0)+1});return r});
 const med=a=>{if(!a.length)return null;const x=[...a].sort((p,q)=>p-q);return x[Math.floor(x.length/2)]};
 const clinics=[...new Set(os.map(o=>o.clinicId))].map(id=>{const l=os.filter(o=>o.clinicId===id);return {id,name:(clinicOf(id)||{}).name||id,n:l.length,rel:l.filter(o=>o.releasedAt).length,rej:l.filter(o=>o.status==="Rejected").length,chg:l.reduce((a,o)=>a+orderCharge(o),0),last:Math.max(...l.map(o=>o.createdAt))}}).sort((a,b)=>b.n-a.n);
 const tests={};os.forEach(o=>o.tests.forEach(c=>{tests[c]=(tests[c]||0)+1}));
 const payers={};os.forEach(o=>{const b=o.billType||BILLFROM[(patientOf(o.patientId)||{ins:{}}).ins.type]||"Unknown";payers[b]=(payers[b]||0)+1});
 const smOf=o=>o.summary||(o.results?orderSummary(o):null);let noSum=0;
 const scr={},conf={};rel.forEach(o=>{const sm=smOf(o);if(!sm){if(o.tests.some(c=>c==="UDS"||isDef(c)))noSum++;return}Object.entries(sm.scr||{}).forEach(([c,v])=>{const n=(SCREEN14.find(x=>x[0]===c)||[c,c])[1];scr[c]=scr[c]||{n,t:0,p:0};scr[c].t++;scr[c].p+=v});Object.entries(sm.conf||{}).forEach(([a,v])=>{conf[a]=conf[a]||{t:0,p:0};conf[a].t++;conf[a].p+=v})});
 const tat=months.map(k=>{const l=rel.filter(o=>monthKey(o.collectedAt)===k);const m=med(l.map(o=>o.releasedAt-o.collectedAt));return {k,n:l.length,m}});
 const hrs=ms=>ms==null?"—":ms<2*DAY?`${(ms/36e5).toFixed(1)} h`:`${(ms/DAY).toFixed(1)} d`;
 const tbl=(h,rows)=>`<div class="tbl-wrap"><table class="tbl"><thead><tr>${h.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")||`<tr><td colspan="${h.length}" class="small muted">No data in this period.</td></tr>`}</tbody></table></div>`;
 return `<div class="page-h"><div><h1>Reports</h1><p class="muted">Volume, test mix, positivity and turnaround. No patient information.${loading?" Loading the full period…":""}</p></div><div class="row">${noSum&&can("*")?`<button class="btn" data-a="rpRebuild" ${RP.rebuilding?"disabled":""}>${RP.rebuilding?`Rebuilding… ${RP.rebuilt||0}`:`Rebuild statistics (${noSum} older order${noSum===1?"":"s"})`}</button>`:""}<button class="btn" data-a="rpExport">${I.down} Export CSV</button></div></div>
 <div class="row" style="margin-bottom:16px;gap:8px;flex-wrap:wrap">${[3,6,12].map(m=>`<span class="pill ${RP.months===m?"on":""}" data-a="rpMonths" data-val="${m}">Last ${m} months</span>`).join("")}<select class="input" style="width:auto;margin-left:auto" data-b="rp.clinic" data-live="1"><option value="">All clinics</option>${S.clinics.map(c=>`<option value="${c.id}" ${RP.clinic===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div>
 <div class="stack"><div class="stats"><div class="stat"><div class="v">${os.length}</div><div class="k">Orders</div></div><div class="stat"><div class="v">${new Set(os.map(o=>o.patientId)).size}</div><div class="k">Patients</div></div><div class="stat"><div class="v">${rel.length}</div><div class="k">Released</div></div>${money_?`<div class="stat"><div class="v">${money(os.reduce((a,o)=>a+orderCharge(o),0))}</div><div class="k">Gross charges billed</div></div>`:`<div class="stat"><div class="v">${clinics.length}</div><div class="k">Ordering clinics</div></div>`}</div>
 <div class="panel"><div class="panel-h"><h2>Orders by month</h2></div><div class="panel-b">${barChart(vol,cats.map(([k,n,c])=>({k,n,c})),{label:"Orders by month"})}</div></div>
 <div class="panel"><div class="panel-h"><h2>Clinics</h2></div>${tbl(["Clinic","Orders","Released","Rejected",...(money_?["Gross charges"]:[]),"Last order"],clinics.map(c=>`<tr><td class="nm small">${esc(c.name)}</td><td class="small">${c.n}</td><td class="small">${c.rel}</td><td class="small">${c.n?(c.rej/c.n*100).toFixed(1):"0.0"}%</td>${money_?`<td class="small">${money(c.chg)}</td>`:""}<td class="small">${fmtD(c.last)}</td></tr>`))}</div>
 <div class="grid g2"><div class="panel"><div class="panel-h"><h2>Test mix</h2></div>${tbl(["Test","Orders"],Object.entries(tests).sort((a,b)=>b[1]-a[1]).map(([c,n])=>`<tr><td class="small">${esc(T(c).name)}</td><td class="small">${n}</td></tr>`))}</div>
 <div class="panel"><div class="panel-h"><h2>Payer mix</h2></div>${tbl(["Billing type","Orders","Share"],Object.entries(payers).sort((a,b)=>b[1]-a[1]).map(([b,n])=>`<tr><td class="small">${esc(b)}</td><td class="small">${n}</td><td class="small">${(n/os.length*100).toFixed(1)}%</td></tr>`))}</div></div>
 <div class="grid g2"><div class="panel"><div class="panel-h"><h2>Screen positivity</h2></div>${tbl(["Drug","Screened","Positive","Rate"],Object.values(scr).sort((a,b)=>b.p/b.t-a.p/a.t).map(x=>`<tr><td class="small">${esc(x.n)}</td><td class="small">${x.t}</td><td class="small">${x.p}</td><td class="small">${(x.p/x.t*100).toFixed(1)}%</td></tr>`))}</div>
 <div class="panel"><div class="panel-h"><h2>Confirmation positivity</h2></div>${tbl(["Analyte","Tested","Positive","Rate"],Object.entries(conf).sort((a,b)=>b[1].p-a[1].p).slice(0,25).map(([n,x])=>`<tr><td class="small">${esc(n)}</td><td class="small">${x.t}</td><td class="small">${x.p}</td><td class="small">${(x.p/x.t*100).toFixed(1)}%</td></tr>`))}</div></div>
 <div class="panel"><div class="panel-h"><h2>Turnaround by month</h2></div>${tbl(["Month","Released","Median collection to release"],tat.map(x=>`<tr><td class="small">${monthLabel(x.k)}</td><td class="small">${x.n}</td><td class="small">${hrs(x.m)}</td></tr>`))}</div></div>`}

/* ---------- client invoices ---------- */
const clientPrice=(c,cpt)=>{const m={};String((c&&c.clientPricesText)||"").split(/\n|,/).forEach(l=>{const [k,v]=l.split("=").map(x=>x&&x.trim());if(k&&isFinite(parseFloat(v)))m[k.toUpperCase()]=parseFloat(v)});return cpt.toUpperCase() in m?m[cpt.toUpperCase()]:(parseFloat(S.fees[cpt])||0)};
function invoiceCandidates(period){return S.orders.filter(o=>o.status==="Released"&&o.billType==="Client bill"&&!o.invoiceId&&monthKey(o.collectedAt)===period)}
function invoiceLines(o){const c=clinicOf(o.clinicId),p=patientOf(o.patientId)||{};const cpts=[];o.tests.forEach(code=>{(isDef(code)?[gcode(classCount(o.confirm))]:T(code).cpt.split(/,\s*/)).forEach(x=>x&&cpts.push(x))});
 return {orderId:o.id,accession:o.accession,date:o.collectedAt,patient:`${p.last||""}, ${p.first||""}`,tests:o.tests.map(x=>testLabel(o,x)).join("; "),cpts,amount:cpts.reduce((a,x)=>a+clientPrice(c,x),0)}}
function invoiceDoc(inv){const c=clinicOf(inv.clinicId)||{},L=S.lab;return `<div class="paper">${paperHead("Invoice",null)}
 <div class="meta"><div><span>Invoice</span><b>${esc(inv.id)}</b></div><div><span>Period</span><b>${monthLabel(inv.period)}</b></div><div><span>Due</span><b>${fmtD(inv.dueAt)}</b></div><div><span>Bill to</span><b>${esc(c.name||"")}${c.acct?` (${esc(c.acct)})`:""}</b></div><div><span>Address</span><b>${esc([c.address,c.city,c.state,c.zip].filter(Boolean).join(", "))}</b></div><div><span>Status</span><b>${esc(inv.status)}${inv.paidAt?` ${fmtD(inv.paidAt)}`:""}</b></div></div>
 <div class="sect"><table><thead><tr><th>Date</th><th>Accession</th><th>Patient</th><th>Tests</th><th>Codes</th><th style="text-align:right">Amount</th></tr></thead><tbody>${inv.lines.map(l=>`<tr><td>${fmtD(l.date)}</td><td>${esc(l.accession)}</td><td>${esc(l.patient)}</td><td>${esc(l.tests)}</td><td>${esc(l.cpts.join(", "))}</td><td style="text-align:right">${money(l.amount)}</td></tr>`).join("")}<tr><td colspan="5" style="text-align:right"><b>Total due</b></td><td style="text-align:right"><b>${money(inv.total)}</b></td></tr></tbody></table></div>
 <div class="sect small">Please remit to ${esc(L.name)}, ${esc(L.address||"")}. Questions: ${esc(L.phone||"")}. Reference ${esc(inv.id)} with your payment.</div></div>`}
function vInvoices(){const list=[...(S.invoices||[])].sort((a,b)=>b.createdAt-a.createdAt);
 return `<div class="page-h"><div><h1>Invoices</h1><p class="muted">Monthly invoices for tests billed to your clinic.</p></div></div><div class="panel">${list.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Invoice</th><th>Period</th><th>Orders</th><th>Total</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>${list.map(i=>`<tr><td class="acc small">${esc(i.id)}</td><td class="small">${monthLabel(i.period)}</td><td class="small">${i.lines.length}</td><td class="small">${money(i.total)}</td><td class="small">${fmtD(i.dueAt)}</td><td>${i.status==="Paid"?'<span class="badge st-released">Paid</span>':'<span class="badge st-pending">Unpaid</span>'}</td><td style="text-align:right"><button class="btn sm" data-a="invView" data-id="${i.id}">View</button></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">No invoices.</div>`}</div>`}

/* ---------- ANSI X12 837P (005010X222A1) claim file ---------- */
function x837(cls){const L=S.lab,e=v=>String(v??"").toUpperCase().replace(/[*~:^]/g," ").replace(/\s+/g," ").trim(),d8=t=>ymd(t),now=new Date(),hm=`${String(now.getHours()).padStart(2,"0")}${String(now.getMinutes()).padStart(2,"0")}`;
 const ctrl=String(Date.now()%1e9).padStart(9,"0"),gctrl=String(Date.now()%1e6),sub=e(L.x12Submitter||L.npi||"FBG"),rcv=e(L.x12Receiver||"RECEIVER"),pad=v=>(v+" ".repeat(15)).slice(0,15);
 const addr=String(L.address||"").match(/^(.*?),\s*([^,]+?),?\s+([A-Z]{2})\s+(\d{5}(?:-\d{4})?)$/i)||[];
 const segs=[`ISA*00*${" ".repeat(10)}*00*${" ".repeat(10)}*ZZ*${pad(sub)}*ZZ*${pad(rcv)}*${d8(now).slice(2)}*${hm}*^*00501*${ctrl}*0*${L.x12Mode==="P"?"P":"T"}*:`,
  `GS*HC*${sub}*${rcv}*${d8(now)}*${hm}*${gctrl}*X*005010X222A1`];
 const body=[`ST*837*0001*005010X222A1`,`BHT*0019*00*${ctrl}*${d8(now)}*${hm}*CH`,`NM1*41*2*${e(L.x12SubmitterName||L.name)}*****46*${sub}`,`PER*IC*${e(L.x12Contact||L.name)}*TE*${String(L.phone||"").replace(/\D/g,"")}`,`NM1*40*2*${e(L.x12ReceiverName||L.billingCo||"RECEIVER")}*****46*${rcv}`,
  `HL*1**20*1`,`PRV*BI*PXC*291U00000X`,`NM1*85*2*${e(L.name)}*****XX*${L.npi}`,`N3*${e(addr[1]||L.address)}`,`N4*${e(addr[2]||"")}*${e(addr[3]||"")}*${String(addr[4]||"").replace(/-/g,"")}`,`REF*EI*${String(L.taxId||"").replace(/\D/g,"")}`];
 let hl=1;const done=[];
 cls.forEach(cl=>{const o=orderOf(cl.orderId),p=patientOf(cl.patientId),pr=provOf(o)||{},bt=o.billType||BILLFROM[p.ins.type],lines=cl.lines.filter(l=>l.billTo==="Payer");if(!lines.length)return;
  const parts=String(pr.name||"").replace(/^dr\.?\s+/i,"").split(" "),plast=parts.pop()||"",pfirst=parts.join(" "),icd=o.icd.slice(0,12).map(c=>c.replace(/\./g,"").toUpperCase()),total=lines.reduce((a,l)=>a+lineCharge(l)*l.units,0);
  hl++;body.push(`HL*${hl}*1*22*0`,`SBR*P*18*${e(p.ins.group)}******${bt==="Medicare"?"MB":bt==="Medicaid"?"MC":"CI"}`,`NM1*IL*1*${e(p.last)}*${e(p.first)}****MI*${e(p.ins.member)}`,`N3*${e(p.address)}`,`N4*${e(p.city)}*${e(p.state)}*${String(p.zip||"").replace(/-/g,"")}`,`DMG*D8*${String(p.dob).replace(/-/g,"")}*${p.sex==="M"?"M":p.sex==="F"?"F":"U"}`,
   `NM1*PR*2*${e(p.ins.payer||bt)}*****PI*${e(p.ins.payerId||"")}`,`CLM*${e(cl.id)}*${total.toFixed(2)}***81:B:1*Y*A*Y*Y`,`HI*${icd.map((c,i)=>`${i?"ABF":"ABK"}:${c}`).join("*")}`,`NM1*DN*1*${e(plast)}*${e(pfirst)}****XX*${pr.npi||""}`);
  lines.forEach((l,i)=>body.push(`LX*${i+1}`,`SV1*HC:${l.cpt}${l.mod?":"+l.mod:""}*${(lineCharge(l)*l.units).toFixed(2)}*UN*${l.units}***${icd.slice(0,4).map((_,k)=>k+1).join(":")}`,`DTP*472*D8*${d8(o.collectedAt)}`));done.push(cl)});
 body.push(`SE*${body.length+1}*0001`);
 return {text:[...segs,...body,`GE*1*${gctrl}`,`IEA*1*${ctrl}`].map(x=>x+"~").join("\n"),claims:done}}
function x837Issues(cls){const is=[];cls.forEach(cl=>{const o=orderOf(cl.orderId),p=patientOf(cl.patientId);if(cl.lines.some(l=>l.billTo==="Payer")&&!(p.ins.payerId||"").trim())is.push(`${cl.id}: payer ID missing (edit the patient's insurance)`)});
 if(!S.lab.x12Submitter)is.push("Lab settings: 837 submitter ID not set");if(!S.lab.x12Receiver)is.push("Lab settings: 837 receiver ID not set");
 if(!/^(.*?),\s*([^,]+?),?\s+([A-Z]{2})\s+(\d{5}(?:-\d{4})?)$/i.test(String(S.lab.address||"")))is.push('Lab settings: address must read like "1830 S. Alma School Rd Ste 134, Mesa, AZ 85210"');return is}

/* ---------- courier pickups and chain of custody ---------- */
const PK={tab:"open",mine:false,staff:null};let pkf=null;
const PK_TYPES=["Urine","Oral fluid","Blood","Swab","Nail","Other"],PK_TEMPS=["Ambient","Refrigerated","Frozen"];
function pkBadge(st){const c={Requested:"st-pending",Assigned:"st-received","Picked up":"st-inprocess",Delivered:"st-released",Cancelled:"st-rejected"}[st]||"";return `<span class="badge ${c}">${esc(st)}</span>`}
function pkTimeline(x){return (x.history||[]).map(h=>`<div class="small">${fmtDT(h.at)} · <b>${esc(h.s)}</b>${h.by?` · ${esc(h.by)}`:""}${h.note?` · ${esc(h.note)}`:""}</div>`).join("")}
function blankPickup(c){const t=new Date(Date.now()+36e5-new Date().getTimezoneOffset()*6e4).toISOString().slice(0,16);return {clinicId:c?c.id:"",readyAt:t,count:"",types:[],temp:"Ambient",contact:(c&&c.phone)||"",notes:""}}
function pickupForm(lab){const f=pkf;return `<div class="grid g2">${lab?`<div class="field spanall"><label class="req">Clinic</label><select class="input" data-b="pkf.clinicId"><option value="">Choose a clinic</option>${S.clinics.filter(c=>c.status==="active").map(c=>`<option value="${c.id}" ${f.clinicId===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select></div>`:""}
 <div class="field"><label class="req">Ready for pickup</label><input class="input" type="datetime-local" data-b="pkf.readyAt" value="${esc(f.readyAt)}"></div><div class="field"><label class="req">Number of specimens</label><input class="input" inputmode="numeric" data-b="pkf.count" value="${esc(f.count)}"></div>
 <div class="field spanall"><label>Specimen types</label><div class="radio-row">${PK_TYPES.map(t=>`<span class="pill ${f.types.includes(t)?"on":""}" data-a="pkType" data-val="${t}">${t}</span>`).join("")}</div></div>
 <div class="field"><label>Storage</label><select class="input" data-b="pkf.temp">${PK_TEMPS.map(t=>`<option ${f.temp===t?"selected":""}>${t}</option>`).join("")}</select></div><div class="field"><label>Contact phone</label><input class="input" data-b="pkf.contact" value="${esc(f.contact)}"></div>
 <div class="field spanall"><label>Notes</label><textarea class="input" data-b="pkf.notes" placeholder="Where to pick up, gate code, hours">${esc(f.notes)}</textarea></div></div>`}
function vPickups(){const lab=isLab(),now=Date.now();
 if(!lab){const c=myClinic(),list=(S.pickups||[]).filter(x=>x.clinicId===c.id).sort((a,b)=>b.requestedAt-a.requestedAt);if(!pkf||pkf.clinicId!==c.id)pkf=blankPickup(c);
  return `<div class="page-h"><div><h1>Pickups</h1><p class="muted">Request a courier pickup and follow your specimens to the lab.</p></div></div>
  <div class="stack"><div class="panel"><div class="panel-h"><h2>Request a pickup</h2></div><div class="panel-b">${pickupForm(false)}<div class="row" style="margin-top:14px"><button class="btn primary" data-a="pkSubmit">Request pickup</button></div></div></div>
  <div class="panel"><div class="panel-h"><h2>Your pickups</h2></div>${list.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Pickup</th><th>Ready</th><th>Specimens</th><th>Status</th><th></th></tr></thead><tbody>${list.map(x=>`<tr><td class="acc small">${x.number}</td><td class="small">${fmtDT(x.readyAt)}</td><td class="small">${x.count} · ${esc(x.types.join(", "))}</td><td>${pkBadge(x.status)}${x.collector?`<div class="xs muted">${esc(x.collector)}</div>`:""}</td><td style="text-align:right"><button class="btn sm ghost" data-a="pkView" data-id="${x.id}">Details</button>${x.status==="Requested"?` <button class="btn sm ghost" data-a="pkCancel" data-id="${x.id}">Cancel</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:`<div class="empty">No pickups yet.</div>`}</div></div>`}
 if(PK.staff===null){PK.staff=[];DB.profilesAll().then(ps=>{PK.staff=ps.filter(p=>p.role==="lab"&&p.active!==false&&(p.lab_roles||[]).some(r=>["collector","admin","reporting"].includes(r)));render()}).catch(()=>{})}
 const all=[...(S.pickups||[])].sort((a,b)=>a.readyAt-b.readyAt),meName=me().name;
 let list=PK.tab==="open"?all.filter(x=>["Requested","Assigned","Picked up"].includes(x.status)):PK.tab==="today"?all.filter(x=>x.status==="Delivered"&&now-x.deliveredAt<DAY):all.slice().reverse();
 if(PK.mine)list=list.filter(x=>x.collector===meName);
 return `<div class="page-h"><div><h1>Pickups</h1><p class="muted">Courier requests from clinics, collector assignments and chain of custody.</p></div><button class="btn primary" data-a="pkNew">${I.plus} Schedule pickup</button></div>
 <div class="row" style="margin-bottom:16px;gap:8px;flex-wrap:wrap">${[["open",`Open (${all.filter(x=>["Requested","Assigned","Picked up"].includes(x.status)).length})`],["today","Delivered today"],["all","All"]].map(([v,l])=>`<span class="pill ${PK.tab===v?"on":""}" data-a="pkTab" data-val="${v}">${l}</span>`).join("")}<label class="check small" style="margin-left:auto"><input type="checkbox" data-a="pkMine" ${PK.mine?"checked":""}>Assigned to me</label></div>
 <div class="panel">${list.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Pickup</th><th>Clinic</th><th>Ready</th><th>Specimens</th><th>Collector</th><th>Status</th><th></th></tr></thead><tbody>${list.map(x=>{const c=clinicOf(x.clinicId)||{};return `<tr><td class="acc small"><button class="link" data-a="pkView" data-id="${x.id}">${x.number}</button></td><td class="small nm">${esc(c.name||"")}<div class="xs muted">${esc(c.address||"")}${c.city?`, ${esc(c.city)}`:""}</div></td><td class="small" style="${x.status!=="Delivered"&&x.readyAt<now-2*36e5?"color:var(--danger);font-weight:600":""}">${fmtDT(x.readyAt)}</td><td class="small">${x.count} · ${esc(x.types.join(", ")||"—")}<div class="xs muted">${esc(x.temp)}</div></td><td class="small">${esc(x.collector||"—")}</td><td>${pkBadge(x.status)}</td>
  <td style="text-align:right;white-space:nowrap">${x.status==="Requested"||x.status==="Assigned"?`<button class="btn sm" data-a="pkAssign" data-id="${x.id}">${x.collector?"Reassign":"Assign"}</button> `:""}${x.status==="Assigned"?`<button class="btn sm primary" data-a="pkPicked" data-id="${x.id}">Picked up</button>`:""}${x.status==="Picked up"?`<button class="btn sm primary" data-a="pkDelivered" data-id="${x.id}">Delivered</button>`:""}</td></tr>`}).join("")}</tbody></table></div>`:`<div class="empty">Nothing here.</div>`}</div>`}
function pkLog(x,s2,note){x.history=[...(x.history||[]),{s:s2,at:Date.now(),by:me().name,note:note||""}]}

/* ---------- HL7 v2.5.1: results out (ORU^R01) and reference-lab results in ---------- */
const h7e=v=>String(v??"").replace(/\\/g,"\\E\\").replace(/\|/g,"\\F\\").replace(/\^/g,"\\S\\").replace(/~/g,"\\R\\").replace(/&/g,"\\T\\").replace(/[\r\n]+/g," ");
const h7ts=t=>{const d=new Date(t);if(isNaN(d))return "";const z=n=>String(n).padStart(2,"0");return `${d.getFullYear()}${z(d.getMonth()+1)}${z(d.getDate())}${z(d.getHours())}${z(d.getMinutes())}${z(d.getSeconds())}`};
const h7seg=(name,f)=>{const max=Math.max(0,...Object.keys(f).map(Number));const a=[name];for(let i=1;i<=max;i++)a.push(f[i]??"");return a.join("|")};
function oruHL7(o,model){const p=patientOf(o.patientId),c=clinicOf(o.clinicId)||{},pr=provOf(o)||{},L=S.lab,m=model||rvModel(o),corr=m.status==="CORRECTED",st=corr?"C":"F";
 const parts=String(pr.name||"").split(" "),plast=parts.pop()||"",pfirst=parts.join(" "),doc=`${pr.npi||""}^${h7e(plast)}^${h7e(pfirst)}^^^^${h7e(pr.cred||"")}^^NPI`;
 const segs=[`MSH|^~\\&|FBG_LIMS|${h7e(L.name)}^${h7e(L.clia||"")}^CLIA|EMR|${h7e(c.name)}|${h7ts(Date.now())}||ORU^R01^ORU_R01|${o.accession}${h7ts(Date.now())}|P|2.5.1`,
  h7seg("PID",{1:"1",3:`${h7e(p.mrn)}^^^FBG^MR`,5:`${h7e(p.last)}^${h7e(p.first)}`,7:String(p.dob||"").replace(/-/g,""),8:p.sex==="X"?"U":p.sex,11:`${h7e(p.address)}^^${h7e(p.city)}^${h7e(p.state)}^${h7e(p.zip)}`,13:h7e(p.phone)}),
  h7seg("ORC",{1:"RE",2:o.accession,3:o.accession,5:"CM",12:doc})];
 let obr=0,obx=0;
 o.tests.forEach(code=>{const t=T(code);obr++;segs.push(h7seg("OBR",{1:obr,2:o.accession,3:o.accession,4:`${code}^${h7e(testLabel(o,code))}^L`,7:h7ts(o.collectedAt),14:h7ts((o.history.find(h=>h.s==="Received")||{}).at),16:doc,22:h7ts(o.releasedAt),24:routeOf(code)==="ref"?"REF":"LAB",25:st}));
  if(isDef(code)){const C=compliance(o);C.an.forEach(a=>{obx++;const s2=C.status(a.key);segs.push(h7seg("OBX",{1:obx,2:"ST",3:`${a.key.toUpperCase()}^${h7e(a.name)}^L`,5:h7e(a.resulted?(a.pos?`POSITIVE${a.meas?` ${a.meas}`:""}`:"NEGATIVE"):"PENDING"),6:"ng/mL",7:h7e(`<${a.cutoff}`),8:a.pos?"A":"N",11:st,14:h7ts(o.collectedAt),19:h7ts(o.releasedAt)}));if(s2.text&&s2.text!=="Consistent Result")segs.push(h7seg("NTE",{1:obx,3:h7e(s2.text)}))});return}
  const R=(o.results||{})[code]||{};analytesFor(o,t).forEach(a=>{const r=R[a.name];if(!r||r.v===""||r.v==null)return;obx++;const q=a.type==="quant"||a.type==="calc",num=q&&isFinite(parseFloat(r.v)),f=flagOf(a,r,p);
   segs.push(h7seg("OBX",{1:obx,2:num?"NM":"ST",3:`${code}-${h7e(a.name).replace(/\s+/g,"_").toUpperCase()}^${h7e(a.name)}^L`,5:h7e(r.v),6:q?h7e(a.unit||""):"",7:h7e(q?rangeText(a,p):a.cutoff?`<${a.cutoff}`:""),8:f==="C"?(String(r.v).startsWith("<")||parseFloat(r.v)<(a.lo??-Infinity)?"LL":"HH"):f||"N",11:st,14:h7ts(o.collectedAt),19:h7ts(o.releasedAt)}));
   if(r.c)segs.push(h7seg("NTE",{1:obx,3:h7e(r.c)}))})});
 if(corr){const lc=(o.corrections||[]).slice(-1)[0];if(lc)segs.push(h7seg("NTE",{1:"1",2:"L",3:h7e(`Corrected report. Reason: ${lc.reason}`)}))}
 return segs.join("\r")}
/* ---------- Amico DX: ready-to-send list, HL7 ORM^O01 orders out, status back ---------- */
function refReadyPanel(pend){const am=AM(),sel=pend.filter(o=>ui.rsel[o.id]),nA=sel.filter(o=>refDest(o)==="amico").length,nO=sel.length-nA;
 const help=am.on?`Pick where each specimen goes. ${esc(am.name)} gets its orders electronically in Icarus; ${esc(otherLab())} gets a printed manifest.`:`Molecular and blood tests go to ${esc(S.lab.refLab||"your reference lab (set its name in Lab settings)")}.${can("settings")?` To send orders to Amico DX electronically, turn it on in <button class="link" data-a="go" data-v="labset">Lab settings</button>.`:""}`;
 const btns=`${am.on?`<button class="btn primary" data-a="sendAmico" ${nA?"":"disabled"}>${I.send} Send to ${esc(am.name)}${nA?` (${nA})`:""}</button>`:""}<button class="btn ${am.on?"":"primary"}" data-a="makeManifest" ${nO?"":"disabled"}>${am.on?`Manifest for ${esc(otherLab())}`:"Create manifest"}${nO?` (${nO})`:""}</button>`;
 if(!pend.length)return `<div class="panel"><div class="panel-h"><div><h2>Ready to send</h2><p class="small muted">${help}</p></div></div>${miniOrders(pend,"rsel")}</div>`;
 const all=pend.every(o=>ui.rsel[o.id]);
 return `<div class="panel"><div class="panel-h" style="flex-wrap:wrap;gap:10px"><div><h2>Ready to send</h2><p class="small muted" style="max-width:70ch">${help}</p></div><div class="row" style="gap:8px;flex-wrap:wrap">${btns}</div></div>
 <div class="tbl-wrap"><table class="tbl"><thead><tr><th style="width:40px"><input type="checkbox" data-a="refSelAll" ${all?"checked":""} aria-label="Select all"></th><th>Accession</th><th>Patient</th><th>Clinic</th><th>Tests</th><th>Received</th>${am.on?"<th>Send to</th>":""}</tr></thead><tbody>${pend.map(o=>{const p=patientOf(o.patientId),miss=amicoMissing(o),d=refDest(o);
  return `<tr><td><input type="checkbox" data-a="toggleSel" data-k="rsel" data-id="${o.id}" ${ui.rsel[o.id]?"checked":""} aria-label="Select ${o.accession}"></td><td><button class="link acc" data-a="openOrder" data-id="${o.id}">${o.accession}</button>${o.stat?' <span class="flag C">STAT</span>':""}</td><td class="nm small">${esc(pname(p))}</td><td class="small">${esc(clinicOf(o.clinicId).name)}</td><td class="small">${refTests(o).map(c=>`<span class="tag">${c}</span>`).join("")}</td><td class="small">${fmtDT(o.history.find(h=>h.s==="Received")?.at)}</td>${am.on?`<td><select class="input" style="height:32px;min-width:170px" data-b="ui.rdest.${o.id}" data-live="1" aria-label="Destination for ${o.accession}"><option value="amico" ${d==="amico"?"selected":""} ${miss.length?"disabled":""}>${esc(am.name)}</option><option value="other" ${d==="other"?"selected":""}>${esc(otherLab())}</option></select>${miss.length?`<div class="xs muted" style="margin-top:3px">${esc(am.name)} isn't set up for ${miss.join(", ")}</div>`:""}</td>`:""}</tr>`}).join("")}</tbody></table></div></div>`}

async function sendAmico(){const am=AM();if(!am.on)return toast(`Turn on ${am.name} referrals in Lab settings first.`);
 const list=refPending().filter(o=>ui.rsel[o.id]&&refDest(o)==="amico");if(!list.length)return toast(`Select specimens going to ${am.name}.`);
 const id="MAN"+ymd(Date.now()).slice(2)+"-"+rid(),at=Date.now();
 const rows=list.map(o=>({dest:"amico",status:"queued",manifest:id,order_id:o.id,accession:o.accession,tests:refTests(o),message:ormHL7(o,refTests(o),id)}));
 try{await DB.referralsQueue(rows)}catch(err){ui.amFail={id,at,ids:list.map(o=>o.id)};
  return modal("Orders weren't sent",`<p class="small">${esc(errMsg(err))}</p><p class="small" style="margin-top:10px">Nothing was marked as sent. Fix the problem and try again, or download the orders as an HL7 file to get them to ${esc(am.name)} another way. Downloading marks the specimens as sent on manifest ${id}.</p>`,{foot:`<button class="btn" data-a="closeModal">Close</button><button class="btn primary" data-a="amDlFail">${I.down} Download HL7 and mark sent</button>`})}
 finishAmico(list,id,at,true)}

function finishAmico(list,id,at,electronic){const am=AM();
 list.forEach(o=>{o.sendout={manifest:id,at,tests:refTests(o),lab:am.name,dest:"amico",electronic};markInProcess(o,`Sent to ${am.name} on ${id}${electronic?" (electronic order to Icarus)":" (HL7 file)"}`);delete ui.rsel[o.id];delete ui.rdest[o.id]});
 RF.key="";save();render();showManifest(id);
 if(!electronic)return toast(`Manifest ${id} created`);
 if(!String(am.email||"").trim())return toast(`${list.length} order${list.length>1?"s":""} sent to ${am.name}. Add a notification email in Lab settings so they're told when a box ships.`);
 DB.referralNotify({manifest:id,specimens:list.length,tests:[...new Set(list.flatMap(o=>refTests(o).map(c=>T(c).name)))]})
  .then(r=>toast(r&&r.ok?`${list.length} order${list.length>1?"s":""} sent. ${am.name} notified.`:`Orders sent, but the notice email failed: ${(r&&r.error)||"unknown error"}`))
  .catch(err=>toast(`Orders sent, but the notice email failed: ${errMsg(err)}`))}

// HL7 v2.5.1 ORM^O01: one ORC/OBR pair per send-out test, with diagnosis codes, for Icarus.
function ormHL7(o,tests,manifest){const p=patientOf(o.patientId)||{},c=clinicOf(o.clinicId)||{},pr=provOf(o)||{},L=S.lab,am=AM(),now=Date.now();
 const parts=String(pr.name||"").split(" "),plast=parts.pop()||"",pfirst=parts.join(" "),doc=`${pr.npi||""}^${h7e(plast)}^${h7e(pfirst)}^^^^${h7e(pr.cred||"")}^^NPI`;
 const segs=[`MSH|^~\\&|FBG_LIMS|${h7e(L.name)}^${h7e(L.clia||"")}^CLIA|${h7e(am.app)}|${h7e(am.facility)}^${h7e(am.clia)}^CLIA|${h7ts(now)}||ORM^O01^ORM_O01|${o.accession}${h7ts(now)}|P|2.5.1`,
  h7seg("PID",{1:"1",3:`${h7e(p.mrn)}^^^FBG^MR`,5:`${h7e(p.last)}^${h7e(p.first)}`,7:String(p.dob||"").replace(/-/g,""),8:p.sex==="X"?"U":p.sex,11:`${h7e(p.address)}^^${h7e(p.city)}^${h7e(p.state)}^${h7e(p.zip)}`,13:h7e(p.phone)}),
  h7seg("PV1",{1:"1",2:"O",3:`^^^${h7e(c.name)}`,7:doc})];
 const ins=p.ins||{};if(am.ins&&ins.type&&ins.type!=="Self-pay"&&ins.payer)segs.push(h7seg("IN1",{1:"1",4:h7e(ins.payer),8:h7e(ins.group),15:h7e(ins.type),36:h7e(ins.member)}));
 tests.forEach((code,i)=>{const t=T(code);
  segs.push(h7seg("ORC",{1:"NW",2:o.accession,4:manifest||"",5:"SC",9:h7ts(now),12:doc,21:h7e(c.name)}));
  segs.push(h7seg("OBR",{1:i+1,2:o.accession,4:`${code}^${h7e(t.name)}^L`,7:h7ts(o.collectedAt),15:`^${h7e(t.specimen)}`,16:doc,27:`^^^^^${o.stat?"S":"R"}`}));
  if(o.notes)segs.push(h7seg("NTE",{1:"1",2:"P",3:h7e(o.notes)}));
  (o.icd||[]).forEach((d,j)=>segs.push(h7seg("DG1",{1:j+1,3:`${h7e(d)}^^I10`,6:"W"})))});
 return segs.join("\r")}

const RF={key:"",by:{},err:"",missing:false};
function refStatusLoad(ids){const key=ids.slice().sort().join(",");if(RF.key===key)return;RF.key=key;
 DB.referralsFor(ids).then(rows=>{RF.missing=rows===null;RF.by={};(rows||[]).sort((a,b)=>String(a.created_at).localeCompare(String(b.created_at))).forEach(r=>{if(r.status!=="cancelled"||!RF.by[r.order_id])RF.by[r.order_id]=r});RF.err="";if(route.v==="instruments")render()}).catch(e=>{RF.err=errMsg(e);if(route.v==="instruments")render()})}
function refStatusCell(o){if(o.sendout.dest!=="amico")return '<span class="faint">Paper manifest</span>';if(!o.sendout.electronic)return '<span class="faint">HL7 file</span>';
 refStatusLoad(S.orders.filter(x=>x.sendout&&x.sendout.dest==="amico"&&inLab(x)).map(x=>x.id));
 if(RF.err)return `<span class="xs muted">Couldn't load: ${esc(RF.err)}</span>`;if(RF.missing)return '<span class="xs muted">Run migration 0012</span>';
 const r=RF.by[o.id];if(!r)return '<span class="faint">…</span>';
 const lbl={queued:["Waiting for Amico","pending"],delivered:["Picked up, not confirmed","received"],accepted:["In Icarus","released"],rejected:["Rejected","rejected"],cancelled:["Cancelled","pending"]}[r.status]||[r.status,"pending"];
 const when=r.acked_at||r.delivered_at;
 return `<span class="badge st-${lbl[1]}">${lbl[0]}</span>${when?`<div class="xs muted" style="margin-top:3px">${fmtDT(when)}</div>`:""}${r.status==="rejected"?`<div class="xs" style="color:var(--danger);margin-top:3px">${esc(r.note||"No reason given")}</div><button class="link xs" data-a="refResend" data-id="${o.id}">Fix the order, then re-send</button>`:""}${r.status==="queued"&&Date.now()-new Date(r.created_at).getTime()>36e5?`<div class="xs muted" style="margin-top:3px">Over an hour: check the connector at ${esc(AM().name)}</div>`:""}`}
function parseHL7(text){const msgs=[];let cur=null;String(text).replace(/^\uFEFF/,"").split(/\r\n|\n|\r/).map(l=>l.trim()).filter(Boolean).forEach(l=>{const f=l.split("|");if(f[0]==="MSH"){cur={segs:[]};msgs.push(cur)}if(cur)cur.segs.push(f)});return msgs}
const h7un=v=>String(v??"").replace(/\\F\\/g,"|").replace(/\\S\\/g,"^").replace(/\\R\\/g,"~").replace(/\\T\\/g,"&").replace(/\\E\\/g,"\\");
function importHL7(text){const msgs=parseHL7(text);if(!msgs.length)return{error:"That file doesn't look like HL7 (no MSH segment)."};
 const map=S.lab.hl7Map||{},per=new Set(),unmatched=new Set(),unmapped=[],seen=new Set();let n=0;
 msgs.forEach(m=>{let o=null,obrCode="";m.segs.forEach(f=>{
  if(f[0]==="ORC"&&!o){const id=String(f[2]||f[3]||"").split("^")[0];if(id)o=findOrderBySample(id)}
  if(f[0]==="OBR"){const id=String(f[2]||f[3]||"").split("^")[0];const x=findOrderBySample(id)||(f[3]?findOrderBySample(String(f[3]).split("^")[0]):null);if(x)o=x;else if(id)unmatched.add(id);obrCode=String(f[4]||"").split("^")[0]}
  if(f[0]==="OBX"&&o){if(!inLab(o)){unmatched.add(o.accession);return}const ids=String(f[3]||"").split("^"),code=ids[0]||"",txt=h7un(ids[1]||""),val=h7un(String(f[5]||"").split("^")[0]),units=h7un(f[6]||"");
   const refTests=o.tests.filter(c=>routeOf(c)==="ref");let target=null;
   const mk=map[code]||map[`${obrCode}|${code}`];if(mk){const [tc,an]=mk.split("|");if(o.tests.includes(tc))target=[tc,an]}
   if(!target){const nn=normName(txt||code);for(const tc of refTests){const a=analytesFor(o,T(tc)).find(a=>a.type!=="calc"&&normName(a.name)===nn);if(a){target=[tc,a.name];break}}}
   if(!target){const k=`${code}|${txt}`;if(!seen.has(k)){seen.add(k);unmapped.push({code,text:txt,units,obr:obrCode})}return}
   o.results[target[0]]=o.results[target[0]]||{};o.results[target[0]][target[1]]={v:val};per.add(o);n++}})});
 per.forEach(o=>{delete o.verified;markInProcess(o,"Results imported from reference lab HL7")});
 return{kind:"hl7",n,orders:[...per],unmatched:[...unmatched],unmapped}}
function hl7Panel(){return `<div class="panel"><div class="panel-h"><div><h2>Import reference lab results (HL7)</h2><p class="small muted">HL7 v2 ORU result files. Results are matched to orders by accession and to tests by code or name.</p></div><div class="row"><button class="btn sm ghost" data-a="hl7MapOpen">Code mapping (${Object.keys(S.lab.hl7Map||{}).length})</button><label class="btn sm primary">${I.up||""} Choose HL7 file<input type="file" accept=".hl7,.txt" data-imp="hl7" hidden></label></div></div></div>`}
function hl7MapModal(){const unm=(ui.lastHL7?importHL7Preview(ui.lastHL7):[]),opts=[];TESTS.filter(t=>!t.dynamic&&routeOf(t.code)==="ref").forEach(t=>(t.analytes||[]).filter(a=>a.type!=="calc").forEach(a=>opts.push([`${t.code}|${a.name}`,`${t.name}: ${a.name}`])));
 const cur=S.lab.hl7Map||{};ui.hmap=ui.hmap||{...cur};unm.forEach(u=>{if(!(u.code in ui.hmap))ui.hmap[u.code]=""});
 const codes=Object.keys(ui.hmap);
 modal("Reference lab code mapping",`<p class="small muted">Link each reference lab result code to the matching test in the portal. Codes whose name already matches a test name are linked automatically.</p>
 ${codes.length?`<div class="tbl-wrap" style="margin-top:12px"><table class="tbl"><thead><tr><th>Their code</th><th>Their name</th><th>Our test</th></tr></thead><tbody>${codes.map(c=>{const u=unm.find(x=>x.code===c)||{};return `<tr><td class="small nm">${esc(c)}</td><td class="small">${esc(u.text||"")}</td><td><select class="input" style="height:32px" data-b="ui.hmap.${c.replace(/\./g,"\u2024")}"><option value="">Not mapped</option>${opts.map(([v,l])=>`<option value="${esc(v)}" ${ui.hmap[c]===v?"selected":""}>${esc(l)}</option>`).join("")}</select></td></tr>`}).join("")}</tbody></table></div>`:`<div class="empty small">No codes yet. Import an HL7 file and any unmatched codes appear here.</div>`}`,{wide:1,foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn primary" data-a="hl7MapSave">Save mapping${ui.lastHL7?" and re-import":""}</button>`})}
function importHL7Preview(text){const saved=JSON.stringify(S.orders.map(o=>[o.id,o.results,o.status,o.verified,o.history.length]));const snap=S.orders.map(o=>({o,r:JSON.parse(JSON.stringify(o.results||{})),s:o.status,v:o.verified,h:o.history.length}));
 const res=importHL7(text);snap.forEach(x=>{x.o.results=x.r;x.o.status=x.s;x.o.verified=x.v;x.o.history.length=x.h});return res.unmapped||[]}

/* ---------- instrument bridge devices (Lab settings) ---------- */
const BD={list:null};
function bridgePanel(){if(BD.list===null){BD.list=[];DB.devicesList().then(l=>{BD.list=l;render()}).catch(()=>{})}
 return `<div class="panel"><div class="panel-h"><div><h2>Instrument bridge</h2><p class="small muted">Computers allowed to send files to the Instrument inbox, including the Amico DX connector. Each gets its own key; deactivate one to cut it off.</p></div><button class="btn sm" data-a="bridgeAdd">${I.plus} Add device</button></div>
 ${BD.list.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Device</th><th>Added</th><th>Last contact</th><th>Status</th><th></th></tr></thead><tbody>${BD.list.map(d=>`<tr><td class="nm small">${esc(d.name)}${d.scope==="amico"?' <span class="tag">Amico DX connector</span>':""}</td><td class="small">${fmtD(d.created_at)}</td><td class="small">${d.last_seen?fmtDT(d.last_seen):"Never"}</td><td>${d.active?'<span class="badge st-released">Active</span>':'<span class="badge">Inactive</span>'}</td><td style="text-align:right"><button class="btn sm ghost" data-a="bridgeToggle" data-id="${d.id}">${d.active?"Deactivate":"Reactivate"}</button></td></tr>`).join("")}</tbody></table></div>`:`<div class="empty small">No devices yet. Add the PC next to the C560 and SCIEX to start sending files automatically.</div>`}</div>`}

/* ---------- specimen labels ---------- */
const LABEL_SIZES={"2x1":[2,1],"2.25x1.25":[2.25,1.25],"3x1":[3,1],"4x2":[4,2]};
const labelCfg=()=>({size:"2x1",copies:1,printer:"browser",...(S.lab.labels||{})});
function labelData(o){const p=patientOf(o.patientId);const specs=[...new Set(o.tests.map(c=>T(c).specimen))];const out=[];specs.forEach((sp,i)=>{for(let k=0;k<(+labelCfg().copies||1);k++)out.push({name:`${p.last}, ${p.first}`,dob:fmtDOB(p.dob),acc:o.accession,suffix:`${i+1}`,spec:sp,collected:fmtDT(o.collectedAt)})});return out}
function labelsZPL(o){const cfg=labelCfg(),[w,h]=LABEL_SIZES[cfg.size]||[2,1],W=Math.round(w*203),H=Math.round(h*203),fs=Math.max(18,Math.round(H/9)),bh=Math.round(H*0.32),z=v=>String(v).replace(/[\^~]/g," ");
 return labelData(o).map(l=>`^XA^CI28^PW${W}^LL${H}^LH0,0
^FO16,10^A0N,${fs+4},${fs+4}^FD${z(l.name)}^FS
^FO16,${14+fs+4}^A0N,${fs},${fs}^FDDOB ${z(l.dob)}  ${z(l.spec)}^FS
^FO16,${22+2*fs+4}^BY2^BCN,${bh},N,N,N^FD${z(l.acc)}^FS
^FO16,${30+2*fs+4+bh}^A0N,${fs},${fs}^FD${z(l.acc)}-${l.suffix}  ${z(l.collected)}^FS
^XZ`).join("\n")}
function printLabels(o){const cfg=labelCfg(),[w,h]=LABEL_SIZES[cfg.size]||[2,1];DB.log("print","orders",o.id,{what:"labels"});
 if(cfg.printer==="zpl"){saveFile(`labels_${o.accession}.zpl`,labelsZPL(o));return toast("ZPL file downloaded. Send it to the Zebra printer.")}
 const svg=v=>{const el=document.createElementNS("http://www.w3.org/2000/svg","svg");try{window.JsBarcode(el,v,{format:"CODE128",height:Math.round(h*28),width:1.4,displayValue:false,margin:0})}catch(e){}return el.outerHTML};
 const html=`<!doctype html><html><head><meta charset="utf-8"><style>@page{size:${w}in ${h}in;margin:0}html,body{margin:0}.l{width:${w}in;height:${h}in;box-sizing:border-box;padding:.06in .1in;font:${h>=1.25?9:7.5}pt/1.2 Arial,sans-serif;overflow:hidden;page-break-after:always}.l b{font-size:${h>=1.25?10.5:8.5}pt}.l svg{display:block;max-width:100%;height:${(h*0.36).toFixed(2)}in;margin:.02in 0}</style></head><body>${labelData(o).map(l=>`<div class="l"><b>${esc(l.name)}</b><br>DOB ${esc(l.dob)} · ${esc(l.spec)}${svg(l.acc)}${esc(l.acc)}-${l.suffix} · ${esc(l.collected)}</div>`).join("")}</body></html>`;
 const f=document.createElement("iframe");f.style.cssText="position:fixed;right:0;bottom:0;width:0;height:0;border:0";document.body.appendChild(f);f.contentDocument.open();f.contentDocument.write(html);f.contentDocument.close();
 setTimeout(()=>{try{f.contentWindow.focus();f.contentWindow.print()}catch(e){}setTimeout(()=>f.remove(),60000)},250)}

/* ---------- claim scrubbing ---------- */
const npiValid=n=>{if(!/^\d{10}$/.test(String(n||"")))return false;const d=("80840"+String(n).slice(0,9)).split("").map(Number);let sum=0;for(let i=d.length-1,alt=true;i>=0;i--,alt=!alt){let x=d[i];if(alt){x*=2;if(x>9)x-=9}sum+=x}return (10-sum%10)%10===+String(n)[9]};
const icdValid=c=>/^[A-Z][0-9][0-9A-Z](\.?[0-9A-Z]{1,4})?$/i.test(String(c||"").trim());
function claimWarnings(cl){const w=[],o=orderOf(cl.orderId),p=patientOf(cl.patientId)||{},bt=o.billType||BILLFROM[p.ins.type];
 const dup=S.claims.filter(x=>x.id!==cl.id&&x.patientId===cl.patientId&&orderOf(x.orderId)&&ymd(orderOf(x.orderId).collectedAt)===ymd(o.collectedAt)&&x.lines.some(l=>cl.lines.some(m=>m.cpt===l.cpt)));if(dup.length)w.push(`Possible duplicate of ${dup.map(x=>x.id).join(", ")} (same patient, date and code)`);
 if(Date.now()-o.collectedAt>300*DAY)w.push("Service date is more than 300 days old; check the payer's timely filing limit");
 if(bt==="Medicare"&&o.tests.some(c=>T(c).abn)&&!(o.consents&&o.consents.abn))w.push("Medicare order with ABN-flagged tests but no ABN on file");
 if(o.icd.length&&o.icd.every(c=>/^Z/i.test(c))&&o.tests.some(c=>c==="UDS"||isDef(c)))w.push("Only Z-codes for drug testing; some payers require a supporting diagnosis");
 return w}

/* ---------- result history, delta checks, review items ---------- */
const DELTA_DEFAULT=[["Sodium","abs",8,7],["Potassium","abs",1,7],["Chloride","abs",8,7],["Carbon Dioxide (CO2)","abs",8,7],["Glucose","pct",50,7],["BUN","pct",50,7],["Creatinine","pct",50,7],["Calcium","abs",1.5,7],["Hemoglobin","abs",2,7],["Hematocrit","abs",6,7],["MCV","abs",5,90],["Platelet Count","pct",50,7],["WBC","pct",50,7]].map(([analyte,type,limit,days])=>({analyte,type,limit,days}));
const RET_DEFAULT={pos:30,neg:14,other:7};
const BATCH_DEFAULT={ionRatioPct:20,isMinPct:50,isMaxPct:150,rtWindow:0.2,calAccPct:20,qcAccPct:20,carryoverPct:20};
const deltaRules=()=>Array.isArray(S.lab.deltaRules)?S.lab.deltaRules:DELTA_DEFAULT;
function prevResult(o,name){const cands=S.orders.filter(x=>x.id!==o.id&&x.patientId===o.patientId&&x.status==="Released"&&x.collectedAt<=o.collectedAt).sort((a,b)=>b.collectedAt-a.collectedAt);
 for(const x of cands)for(const code of Object.keys(x.results||{})){const r=(x.results[code]||{})[name];if(r&&!r.calc&&r.v!==""&&isFinite(parseFloat(r.v)))return {v:parseFloat(r.v),at:x.collectedAt,acc:x.accession}}return null}
function deltaFor(o,name,val){const rule=deltaRules().find(d=>d.analyte===name);if(!rule||!isFinite(val))return null;const pr=prevResult(o,name);if(!pr||(o.collectedAt-pr.at)>(+rule.days||7)*DAY)return {prev:pr,hit:false};
 const diff=Math.abs(val-pr.v),hit=rule.type==="pct"?(pr.v?diff/Math.abs(pr.v)*100>+rule.limit:false):diff>+rule.limit;return {prev:pr,hit,rule}}
function reviewItems(o,R){R=R||o.results||{};const out=[];
 Object.entries(R).forEach(([code,res])=>{if(code==="_id"||!res)return;Object.entries(res).forEach(([name,r])=>{if(!r)return;
  if(Array.isArray(r.review)&&r.review.length)out.push(`${name}: ${r.review.join("; ")}`);
  if(!r.calc&&isFinite(parseFloat(r.v))){const d=deltaFor(o,name,parseFloat(r.v));if(d&&d.hit)out.push(`Delta check, ${name}: ${r.v} now vs ${d.prev.v} on ${fmtD(d.prev.at)} (limit ${d.rule.type==="pct"?d.rule.limit+"%":d.rule.limit})`)}})});return out}
// Returns false if the user cancels, otherwise a history note ("" when nothing needed review).
function confirmReview(o,R,action){const items=reviewItems(o,R);if(!items.length)return "";
 if(!confirm(`Review before you ${action}:\n\n- ${items.slice(0,15).join("\n- ")}${items.length>15?`\n- …and ${items.length-15} more`:""}\n\nConfirm you have reviewed these and they are acceptable to report?`))return false;
 return `Reviewed before ${action}: ${items.join(" | ")}`.slice(0,1500)}
function historyPanel(p){const os=S.orders.filter(o=>o.patientId===p.id&&o.status==="Released").sort((a,b)=>b.collectedAt-a.collectedAt);if(!os.length)return "";
 const qrows={};os.forEach(o=>Object.entries(o.results||{}).forEach(([code,res])=>{const t=T(code);if(!t||t.dynamic)return;analytesFor(o,t).forEach(a=>{if(a.type!=="quant"&&a.type!=="calc")return;const r=(res||{})[a.name];if(!r||r.v===""||r.v==null)return;(qrows[a.name]=qrows[a.name]||{a,vals:{}}).vals[o.id]={v:r.v,f:flagOf(a,r,p)}})}));
 const cols=os.slice(0,6),names=Object.keys(qrows);
 const tox=os.filter(o=>o.tests.some(c=>c==="UDS"||isDef(c)));
 return `${names.length?`<div class="panel"><div class="panel-h"><div><h2>Result history</h2><p class="small muted">Most recent ${cols.length} released order${cols.length===1?"":"s"}</p></div></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Test</th>${cols.map(o=>`<th>${fmtD(o.collectedAt)}<div class="xs muted" style="font-weight:400">${o.accession}</div></th>`).join("")}<th>Reference</th></tr></thead><tbody>${names.map(nm=>{const q=qrows[nm];return `<tr><td class="nm small">${esc(nm)}</td>${cols.map(o=>{const x=q.vals[o.id];return `<td class="small">${x?`${esc(x.v)}${x.f?` <span class="flag ${x.f}">${x.f}</span>`:""}`:'<span class="faint">—</span>'}</td>`}).join("")}<td class="small muted">${rangeText(q.a,p)} ${esc(q.a.unit||"")}</td></tr>`}).join("")}</tbody></table></div></div>`:""}
 ${tox.length?`<div class="panel"><div class="panel-h"><h2>Toxicology history</h2></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>Collected</th><th>Accession</th><th>Screen positives</th><th>Confirmed positives</th><th>Compliance</th></tr></thead><tbody>${tox.map(o=>{const sc=o.tests.includes("UDS")?SCREEN14.filter(([c,n])=>((o.results.UDS||{})[n]||{}).v==="Positive").map(([c])=>c):[];const C=o.tests.some(isDef)?compliance(o):null;
  return `<tr class="click" data-a="openOrder" data-id="${o.id}"><td class="small">${fmtD(o.collectedAt)}</td><td class="small acc">${o.accession}</td><td class="small">${sc.join(", ")||'<span class="muted">None</span>'}</td><td class="small">${C?(C.an.filter(a=>a.pos).map(a=>esc(a.name)).join(", ")||'<span class="muted">None</span>'):"—"}</td><td class="small">${C?(C.unexpected.length||C.missing.length?`<span style="color:var(--danger)">${C.unexpected.length} unexpected, ${new Set(C.missing.map(x=>x.rx)).size} missing</span>`:'<span style="color:var(--ok)">Consistent</span>'):"—"}</td></tr>`}).join("")}</tbody></table></div></div>`:""}`}

/* ---------- specimen storage and retention ---------- */
const SG={tab:"needs",q:"",sel:{}};let stf=null;
const retention=()=>({...RET_DEFAULT,...(S.lab.retention||{})});
function retainDays(o){const R=retention();if(o.tests.every(c=>routeOf(c)==="ref"))return +R.other;const tox=o.tests.some(c=>c==="UDS"||isDef(c));if(!tox)return +R.other;
 const pos=(o.tests.includes("UDS")&&SCREEN14.some(([c,n])=>((o.results.UDS||{})[n]||{}).v==="Positive"))||(o.tests.some(isDef)&&toxAnalytes(o).some(a=>a.pos));return pos?+R.pos:+R.neg}
const storageUnits=()=>(QM.recs||[]).filter(r=>r.kind==="equipment"&&["Refrigerator","Freezer"].includes(r.type)&&r.status!=="Retired").map(r=>r.name);
function vStorage(){if(QM.recs===null&&!QM.loading)setTimeout(qmsLoad,0);const now=Date.now(),q=SG.q.trim().toLowerCase();
 const inLabNow=S.orders.filter(o=>["Received","In Process","Released"].includes(o.status)&&!o.tests.every(c=>routeOf(c)==="ref"));
 const needs=inLabNow.filter(o=>!o.storage&&now-o.collectedAt<60*DAY),stored=S.orders.filter(o=>o.storage&&!o.storage.disposedAt),due=stored.filter(o=>o.storage.retainUntil&&o.storage.retainUntil<now),disposed=S.orders.filter(o=>o.storage&&o.storage.disposedAt).sort((a,b)=>b.storage.disposedAt-a.storage.disposedAt);
 const match=o=>{const p=patientOf(o.patientId)||{};return !q||`${o.accession} ${p.first} ${p.last} ${(o.storage||{}).unit||""} ${(o.storage||{}).rack||""}`.toLowerCase().includes(q)};
 const list={needs,stored,due,disposed}[SG.tab].filter(match);
 const loc=st=>`${esc(st.unit||"")}${st.rack?` · ${esc(st.rack)}`:""}${st.position?` · ${esc(st.position)}`:""}`;
 return `<div class="page-h"><div><h1>Specimen storage</h1><p class="muted">Where each specimen is kept after testing, how long to keep it, and when it was discarded.</p></div></div>
 <div class="row" style="margin-bottom:16px;gap:8px;flex-wrap:wrap">${[["needs",`Needs storing (${needs.length})`],["stored",`Stored (${stored.length})`],["due",`Due for disposal (${due.length})`],["disposed","Disposal log"]].map(([v,l])=>`<span class="pill ${SG.tab===v?"on":""}" data-a="sgTab" data-val="${v}">${l}</span>`).join("")}<span style="flex:1"></span><div class="search" style="min-width:240px">${I.search}<input class="input" data-b="sg.q" data-live="1" value="${esc(SG.q)}" placeholder="Accession, patient or location"></div></div>
 <div class="panel">${SG.tab==="due"&&list.length?`<div class="panel-h"><span class="small muted">${Object.values(SG.sel).filter(Boolean).length} selected</span><button class="btn danger sm" data-a="sgDispose">Record disposal of selected</button></div>`:""}
 ${list.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr>${SG.tab==="due"?"<th></th>":""}<th>Accession</th><th>Patient</th><th>Collected</th>${SG.tab==="needs"?"<th>Status</th>":"<th>Location</th>"}<th>${SG.tab==="disposed"?"Disposed":"Keep until"}</th><th></th></tr></thead><tbody>${list.slice(0,300).map(o=>{const p=patientOf(o.patientId)||{},st=o.storage||{};
  return `<tr>${SG.tab==="due"?`<td><input type="checkbox" data-a="sgSel" data-id="${o.id}" ${SG.sel[o.id]?"checked":""} aria-label="Select ${o.accession}"></td>`:""}<td class="acc small"><button class="link" data-a="openOrder" data-id="${o.id}">${o.accession}</button></td><td class="small">${esc(pname(p))}</td><td class="small">${fmtD(o.collectedAt)}</td>
  ${SG.tab==="needs"?`<td>${badge(o.status)}</td>`:`<td class="small">${loc(st)}</td>`}<td class="small">${SG.tab==="disposed"?`${fmtD(st.disposedAt)} · ${esc(st.disposalMethod||"")}<div class="xs muted">${esc(st.disposedBy||"")}</div>`:st.retainUntil?`<span style="${st.retainUntil<now?"color:var(--danger);font-weight:600":""}">${fmtD(st.retainUntil)}</span>`:"—"}</td>
  <td style="text-align:right">${SG.tab==="disposed"?"":`<button class="btn sm" data-a="sgStore" data-id="${o.id}">${o.storage?"Move":"Store"}</button>`}</td></tr>`}).join("")}</tbody></table></div>`:`<div class="empty">${SG.tab==="needs"?"Every specimen in the lab has a storage location.":SG.tab==="due"?"Nothing is due for disposal.":"Nothing here."}</div>`}</div>
 <p class="xs muted" style="margin-top:10px">Retention: positives ${retention().pos} days, negatives ${retention().neg} days, other specimens ${retention().other} days after storage. Change these in Lab settings.</p>`}
function storeModal(o){const st=o.storage||{},units=storageUnits(),days=retainDays(o);stf={id:o.id,unit:st.unit||units[0]||"",rack:st.rack||"",position:st.position||"",retainUntil:ymd(st.retainUntil||Date.now()+days*DAY,"-")};
 modal(`Store ${o.accession}`,`<div class="grid g3"><div class="field"><label class="req">Refrigerator / freezer</label><input class="input" list="sgunits" data-b="stf.unit" value="${esc(stf.unit)}" placeholder="e.g. Specimen fridge 1"><datalist id="sgunits">${units.map(u=>`<option value="${esc(u)}">`).join("")}</datalist></div><div class="field"><label>Rack or box</label><input class="input" data-b="stf.rack" value="${esc(stf.rack)}"></div><div class="field"><label>Position</label><input class="input" data-b="stf.position" value="${esc(stf.position)}"></div>
 <div class="field"><label class="req">Keep until</label><input class="input" type="date" data-b="stf.retainUntil" value="${esc(stf.retainUntil)}"><span class="hint">Default ${days} days, based on this specimen's results.</span></div></div>${units.length?"":`<p class="xs muted" style="margin-top:10px">Add your refrigerators and freezers under Compliance → Equipment to pick them from a list.</p>`}`,{foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn primary" data-a="sgSave">Save location</button>`})}

