function vSupplies(){const lab=isLab(),list=[...(S.supply_orders||[])].sort((a,b)=>b.createdAt-a.createdAt);
 const st=x=>x.status==="Shipped"?`<span class="badge st-released">Shipped</span>`:x.status==="Cancelled"?`<span class="badge st-rejected">Cancelled</span>`:`<span class="badge st-pending">New</span>`;
 const table=`<div class="panel"><div class="panel-h"><h2>${lab?"Supply orders":"Your supply orders"}</h2>${lab&&can("settings")?`<button class="btn sm ghost" data-a="supCatGo">Edit supply catalog</button>`:""}</div>${list.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Order</th>${lab?"<th>Clinic</th>":""}<th>Items</th><th>Ship to</th><th>Urgency</th><th>Status</th>${lab&&can("supplies")?"<th></th>":""}</tr></thead><tbody>${list.map(x=>`<tr><td><div class="acc">${esc(x.number)}</div><div class="xs muted">${fmtDT(x.createdAt)} · ${esc(x.by||"")}</div></td>${lab?`<td class="small">${esc((clinicOf(x.clinicId)||{}).name||"")}</td>`:""}<td class="small">${x.items.map(i=>`${i.qty} × ${esc(i.name)}`).join("<br>")}</td><td class="small">${esc(x.shipTo.recipient)}<br>${esc(x.shipTo.address)}, ${esc(x.shipTo.city)}, ${esc(x.shipTo.state)} ${esc(x.shipTo.zip)}${x.shipTo.phone?`<br>${esc(x.shipTo.phone)}`:""}${x.notes?`<div class="xs muted">${esc(x.notes)}</div>`:""}</td><td>${x.urgency==="STAT"?'<span class="flag C">STAT</span>':'<span class="small">Routine</span>'}</td><td>${st(x)}${x.shippedAt?`<div class="xs muted">${fmtD(x.shippedAt)}</div>`:""}${x.tracking?`<div class="small" style="margin-top:3px">${esc(x.carrier||"")} ${trackUrl(x.carrier,x.tracking)?`<a href="${trackUrl(x.carrier,x.tracking)}" target="_blank" rel="noopener">${esc(x.tracking)}</a>`:esc(x.tracking)}</div>`:x.status==="Shipped"?`<div class="xs muted">No tracking number</div>`:""}</td>${lab&&can("supplies")?`<td style="text-align:right;white-space:nowrap">${x.status==="New"?`<button class="btn sm primary" data-a="supShip" data-id="${x.id}">Ship</button> <button class="btn sm ghost" data-a="supCancel" data-id="${x.id}">Cancel</button>`:x.status==="Shipped"?`<button class="btn sm" data-a="supShip" data-id="${x.id}">${x.tracking?"Edit tracking":"Add tracking"}</button>`:""}</td>`:""}</tr>`).join("")}</tbody></table></div>`:`<div class="empty"><h3>No supply orders yet</h3></div>`}</div>`;
 if(lab)return `<div class="page-h"><div><h1>Supply orders</h1><p class="muted">Supplies requested by clinics with supply ordering turned on.</p></div></div>${table}`;
 if(!spf)spf=blankSupply();const f=spf;
 return `<div class="page-h"><div><h1>Supplies</h1><p class="muted">Order collection supplies from First Bio Genetics.</p></div></div>
 <div class="stack"><div class="panel"><div class="panel-h"><h2>New supply order</h2></div><div class="panel-b">
  <div class="lbl" style="margin-bottom:8px">Items and quantities</div><div class="defgrid">${supplyItems().map(x=>`<div class="row" style="gap:8px"><input class="input" style="width:76px;height:34px" type="number" min="0" ${x.max?`max="${esc(x.max)}"`:""} inputmode="numeric" data-b="spf.qty.${x.id}" value="${esc(f.qty[x.id]||"")}" aria-label="${esc(x.name)} quantity"><span class="small">${esc(x.name)}${x.unit||x.max?`<br><span class="xs muted">${[x.unit,x.max?`up to ${esc(x.max)} per order`:""].filter(Boolean).join(" · ")}</span>`:""}</span></div>`).join("")}</div>
  <h3 style="margin:20px 0 10px">Ship to</h3><div class="grid g3"><div class="field"><label class="req">Recipient</label><input class="input" data-b="spf.recipient" value="${esc(f.recipient)}"></div><div class="field"><label>Phone</label><input class="input" data-b="spf.phone" value="${esc(f.phone)}"></div><div class="field"><label class="req">Urgency</label><div class="radio-row">${["Routine","STAT"].map(u=>`<span class="pill ${f.urgency===u?"on":""}" data-a="supUrg" data-val="${u}">${u}</span>`).join("")}</div></div>
  <div class="field span2"><label class="req">Street address</label><input class="input" data-b="spf.address" value="${esc(f.address)}"></div><div class="field"><label class="req">City</label><input class="input" data-b="spf.city" value="${esc(f.city)}"></div><div class="field"><label class="req">State</label><input class="input" data-b="spf.state" value="${esc(f.state)}"></div><div class="field"><label class="req">ZIP</label><input class="input" data-b="spf.zip" value="${esc(f.zip)}"></div>
  <div class="field spanall"><label>Notes</label><textarea class="input" data-b="spf.notes" placeholder="Delivery instructions, suite number, etc.">${esc(f.notes)}</textarea></div></div>
  <div class="row" style="margin-top:16px"><button class="btn primary" data-a="supSubmit">Submit supply order</button></div></div></div>${table}</div>`}
const CLINIC_DEFAULTS={ordering:true,supplies:false,resultsScope:"all",mfa:false,vialLabels:false,analytics:false};
const cset=(c,k)=>{const v=c&&c.settings&&c.settings[k];return v===undefined?CLINIC_DEFAULTS[k]:v};
function clinicSettingsForm(f){const st=f.settings||(f.settings={...CLINIC_DEFAULTS});
 return `<h3 style="margin:22px 0 10px">Portal settings</h3><div class="stack" style="gap:10px">
  <label class="check"><input type="checkbox" data-b="clf.settings.ordering" ${cset(f,"ordering")?"checked":""}><span><b>Clinic can place orders in the portal</b><br><span class="small muted">The lab and collectors can always enter orders for the clinic too. Turn off to make the clinic view-only.</span></span></label>
  <label class="check"><input type="checkbox" data-b="clf.settings.supplies" ${cset(f,"supplies")?"checked":""}><span><b>Supply ordering</b><br><span class="small muted">Clinic users can order collection supplies.</span></span></label>
  <label class="check"><input type="checkbox" data-b="clf.settings.mfa" ${cset(f,"mfa")?"checked":""}><span><b>Require two-step verification for this clinic's users</b><br><span class="small muted">Off by default. Clinic users see patient results, so a code from an authenticator app protects them if a password leaks. Changes take effect at their next sign-in. Lab staff always use two-step verification.</span></span></label>
  <label class="check"><input type="checkbox" data-b="clf.settings.vialLabels" ${cset(f,"vialLabels")?"checked":""}><span><b>Custom vial labeling</b><br><span class="small muted">The clinic labels its collection vials with its own barcode (for example Oratek's small vial labels). Orders ask for the vial barcode, and the lab links it to the accession number when the specimen arrives.</span></span></label>
  <label class="check"><input type="checkbox" data-b="clf.settings.analytics" ${cset(f,"analytics")?"checked":""}><span><b>Analytics</b><br><span class="small muted">Clinic users see an Analytics page for their own orders: kit volume, turnaround and normal vs abnormal findings, with a downloadable report.</span></span></label>
  <div class="field"><label>Client prices (for client-bill invoices)</label><textarea class="input" style="max-width:520px;min-height:70px" data-b="clf.clientPricesText" placeholder="80307=25&#10;G0480=60">${esc(f.clientPricesText||"")}</textarea><span class="hint">One code per line as CODE=price. Codes not listed use the charge master.</span></div>
  <div class="field"><label>Who sees results</label><select class="input" style="max-width:520px" data-b="clf.settings.resultsScope"><option value="all" ${cset(f,"resultsScope")==="all"?"selected":""}>Every user at the clinic sees every result</option><option value="provider" ${cset(f,"resultsScope")==="provider"?"selected":""}>Users linked to providers see only their providers' results</option></select><span class="hint">Users not linked to a provider (for example MAs) always see all of the clinic's results.</span></div></div>`}
let clf=null;
function clinicForm(){const f=clf,i=(k,l,o={})=>`<div class="field ${o.cls||""}"><label class="${o.req?"req":""}">${l}</label><input class="input" data-b="clf.${k}" value="${esc(k.split(".").reduce((a,x)=>a?.[x],f)??"")}" ${o.type?`type="${o.type}"`:""}></div>`;
 return `<div class="grid g2">${i("name","Practice name",{req:1,cls:"spanall"})}${i("npi","Group NPI",{req:1})}${i("taxId","Tax ID (EIN)")}${i("specialty","Specialty")}${i("phone","Phone",{req:1})}${i("fax","Fax")}${i("address","Street address",{req:1,cls:"spanall"})}${i("city","City",{req:1})}<div class="grid g2">${i("state","State",{req:1})}${i("zip","ZIP",{req:1})}</div>${i("contactName","Primary contact")}${i("contactEmail","Contact email",{type:"email"})}</div>
 <h3 style="margin:22px 0 10px">Providers</h3>${f.providers.map((p,k)=>`<div class="subbox" style="margin-top:${k?10:0}px"><div class="row between" style="margin-bottom:10px"><b>Provider ${k+1}</b>${f.providers.length>1?`<button class="link" data-a="clfDelProv" data-i="${k}">Remove</button>`:""}</div><div class="grid g3">${i(`providers.${k}.name`,"Full name",{req:1})}${i(`providers.${k}.cred`,"Credentials")}${i(`providers.${k}.npi`,"Individual NPI",{req:1})}${i(`providers.${k}.email`,"Email for result alerts",{type:"email",cls:"span2"})}${i(`providers.${k}.phone`,"Mobile for text alerts")}</div></div>`).join("")}<button class="btn sm" style="margin-top:10px" data-a="clfAddProv">${I.plus} Add provider</button>
 <h3 style="margin:22px 0 10px">Result alerts</h3><div class="stack" style="gap:8px">${[["email","Email the ordering provider"],["sms","Text the ordering provider"],["fax","Fax the report to the practice"]].map(([k,l])=>`<label class="check"><input type="checkbox" data-b="clf.notify.${k}" ${f.notify[k]?"checked":""}>${l}</label>`).join("")}</div><div class="grid g2" style="margin-top:12px">${i("notify.criticalPhone","Phone for critical values",{req:1})}</div>
 ${clinicSettingsForm(f)}
 ${!f.agreement||!(f.agreement.sig||f.agreement.onFile)?`<h3 style="margin:22px 0 10px">Services agreement and BAA</h3><label class="check"><input type="checkbox" data-b="clf.sof.on" ${f.sof&&f.sof.on?"checked":""}>Signed paper onboarding is on file (SOF)</label>${f.sof&&f.sof.on?`<div class="grid g3" style="margin-top:10px"><div class="field"><label>Signed by</label><input class="input" data-b="clf.sof.signer" value="${esc(f.sof.signer)}"></div><div class="field"><label>Title</label><input class="input" data-b="clf.sof.title" value="${esc(f.sof.title)}"></div><div class="field"><label>Date signed</label><input class="input" type="date" data-b="clf.sof.date" value="${esc(f.sof.date)}"></div></div>`:""}`:""}
 ${!f.id?(can("users")?`<h3 style="margin:22px 0 10px">Clinic login</h3><label class="check"><input type="checkbox" data-b="clf.login.on" ${f.login&&f.login.on?"checked":""}>Create the clinic's login now and show the temporary password</label><div class="grid g2" style="margin-top:10px"><div class="field"><label>Username or email</label><input class="input" data-b="clf.login.id" value="${esc((f.login&&f.login.id)||"")}" placeholder="Leave blank to use a username made from the clinic name"></div><div class="field"><label>Name on the login</label><input class="input" data-b="clf.login.name" value="${esc((f.login&&f.login.name)||"")}" placeholder="Defaults to the contact name, or the clinic name"></div></div><p class="xs muted" style="margin-top:6px">Add more logins for providers and MAs later under Users.</p>`:`<p class="xs muted" style="margin-top:16px">An admin creates the clinic's login under Users after the clinic is added.</p>`):""}
 ${!f.id&&can("clinics.approve")?`<label class="check" style="margin-top:16px"><input type="checkbox" data-b="clf.approveNow" ${f.approveNow?"checked":""}>Approve this clinic now</label>`:!f.id?`<p class="xs muted" style="margin-top:16px">The clinic starts as pending until an admin approves it.</p>`:""}`}
const clinicSOF=c=>!!(c&&c.agreement&&c.agreement.onFile);
const clinicUsername=n=>(String(n||"clinic").toLowerCase().replace(/&/g," and ").replace(/[^a-z0-9]+/g,".").replace(/^\.+|\.+$/g,"").slice(0,30)||"clinic").replace(/^([^a-z0-9])/,"c$1").padEnd(3,"0");
function blankClinic(){return {name:"",npi:"",taxId:"",specialty:"",phone:"",fax:"",address:"",city:"",state:"AZ",zip:"",contactName:"",contactEmail:"",providers:[{id:uid("p"),name:"",cred:"",npi:"",email:"",phone:""}],notify:{email:true,sms:false,fax:false,criticalPhone:""},settings:{...CLINIC_DEFAULTS,ordering:false},sof:{on:true,signer:"",title:"",date:ymd(Date.now(),"-")},approveNow:false,login:{on:true,id:"",name:""}}}
function clinicFormModal(){modal(clf.id?`Edit ${clf.name}`:"Add clinic",clinicForm(),{wide:1,foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn primary" data-a="saveClinicForm">${clf.id?"Save changes":"Add clinic"}</button>`})}

/* ---------- users (admin) ---------- */
const US={list:null,loading:false,err:"",tab:"lab"};let uf=null;
async function loadUsers(){if(US.loading)return;US.loading=true;US.err="";render();try{const r=await DB.manageUsers("list");if(!r||!Array.isArray(r.users))throw new Error("The user service answered unexpectedly. Check that the manage-users function in Supabase contains the manage-users code (README section 9).");US.list=r.users}catch(e){US.err=errMsg(e);US.list=US.list||[]}finally{US.loading=false;render()}}
function vUsers(){if(US.list===null&&!US.loading)setTimeout(loadUsers,0);
 const all=US.list||[],lab=all.filter(u=>u.kind==="lab"),cl=all.filter(u=>u.kind==="clinic"),none=all.filter(u=>!u.linked);
 const list=US.tab==="lab"?lab:US.tab==="clinic"?cl:none;
 const tabs=[["lab",`Lab staff (${lab.length})`],["clinic",`Clinic users (${cl.length})`],["none",`No access (${none.length})`]];
 return `<div class="page-h"><div><h1>Users</h1><p class="muted">Who can sign in, and what each person can do. Each lab user's approver ID appears on the reports they approve.</p></div><button class="btn primary" data-a="addUser">${I.plus} Add user</button></div>
 <div class="radio-row" style="margin-bottom:18px">${tabs.map(([v,l])=>`<span class="pill ${US.tab===v?"on":""}" data-a="setUsTab" data-val="${v}">${l}</span>`).join("")}</div>
 ${US.err?`<div class="banner danger" style="margin-bottom:16px">${I.alert}<div>${esc(US.err)}${/manage-users|Failed to send|404/i.test(US.err)?" Deploy the manage-users function (README section 9).":""}</div></div>`:""}
 <div class="panel">${US.list===null?`<div class="empty">Loading…</div>`:list.length?`<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Name</th><th>${US.tab==="clinic"?"Clinic":"Roles"}</th><th>Two-step</th><th>Last sign-in</th><th>Status</th><th></th></tr></thead><tbody>${list.map(u=>`<tr><td><div class="nm">${esc(u.name||u.email)}${u.id===S.session?' <span class="xs muted">(you)</span>':""}</div><div class="xs muted">${u.username?`Username: ${esc(u.username)}`:esc(u.email)}</div>${u.kind==="lab"?`<div class="xs muted">Approver ID: <b>${esc(staffCode(u.name||u.email,u.id))}</b></div>`:""}</td>
  <td class="small">${u.kind==="clinic"?esc((clinicOf(u.clinicId)||{}).name||u.clinicId||""):u.kind==="lab"?u.roles.map(r=>`<span class="tag">${(ROLE_INFO.find(x=>x[0]===r)||[0,r])[1]}</span>`).join(""):'<span class="muted">Not linked</span>'}</td>
  <td class="small">${u.mfa?`<span class="badge st-released">Set up</span>`:`<span class="badge st-pending">Not yet</span>`}</td><td class="small">${u.lastSignIn?fmtDT(u.lastSignIn):"Never"}${u.mustChange?`<div class="xs muted">Temporary password</div>`:""}</td>
  <td>${!u.linked?`<span class="badge">No access</span>`:u.active?`<span class="badge st-active">Active</span>`:`<span class="badge st-suspended">Deactivated</span>`}</td>
  <td style="text-align:right;white-space:nowrap"><button class="btn sm" data-a="editUser" data-id="${u.id}">${u.linked?"Edit":"Give access"}</button>${u.linked?` <button class="btn sm ghost" data-a="userMore" data-id="${u.id}">More</button>`:""}</td></tr>`).join("")}</tbody></table></div>`:`<div class="empty"><h3>No one here yet</h3></div>`}</div>`}
function userForm(){const f=uf,fc=clinicOf(f.clinicId);
 return `<div class="grid g2">${f.id?`<div class="field spanall"><label>Signs in with</label><input class="input" value="${esc(shownLogin(f.email))}" disabled></div>`:`<div class="field spanall"><label class="req">Signs in with</label><div class="radio-row" style="margin-bottom:8px"><span class="pill ${f.signin!=="username"?"on":""}" data-a="ufSet" data-k="signin" data-val="email">Email address</span><span class="pill ${f.signin==="username"?"on":""}" data-a="ufSet" data-k="signin" data-val="username">Username</span></div>${f.signin==="username"?`<input class="input" data-b="uf.username" value="${esc(f.username||"")}" placeholder="e.g. harbor.ma1" autocapitalize="none"><span class="hint">Username accounts can't use "Forgot password"; an admin resets their password here.</span>`:`<input class="input" type="email" data-b="uf.email" value="${esc(f.email)}">`}</div>`}<div class="field spanall"><label class="req">Full name</label><input class="input" data-b="uf.name" value="${esc(f.name)}"></div></div>
 <div class="radio-row" style="margin:18px 0 12px"><span class="pill ${f.kind==="lab"?"on":""}" data-a="ufSet" data-k="kind" data-val="lab">Lab staff</span><span class="pill ${f.kind==="clinic"?"on":""}" data-a="ufSet" data-k="kind" data-val="clinic">Clinic user</span></div>
 ${f.kind==="lab"?`<div class="lbl" style="margin-bottom:8px">Roles</div><div class="stack" style="gap:10px">${ROLE_INFO.map(([k,l,d])=>`<label class="check"><input type="checkbox" data-a="ufRole" data-val="${k}" ${f.roles.includes(k)?"checked":""}><span><b>${l}</b><br><span class="small muted">${d}</span></span></label>`).join("")}</div>`
 :`<div class="field"><label class="req">Clinic</label><select class="input" data-b="uf.clinicId" data-live="1"><option value="">Choose a clinic</option>${[...S.clinics].filter(c=>c.status!=="archived"||c.id===uf.clinicId).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.id}" ${f.clinicId===c.id?"selected":""}>${esc(c.name)}${c.acct?` (${c.acct})`:""}</option>`).join("")}</select><span class="hint">They'll see only this clinic's patients and orders.</span></div>
 ${fc&&fc.providers.length?`<div class="field" style="margin-top:14px"><label>Linked providers</label><div class="stack" style="gap:6px">${fc.providers.map(pv=>`<label class="check"><input type="checkbox" data-a="ufProv" data-val="${pv.id}" ${(f.providerIds||[]).includes(pv.id)?"checked":""}>${esc(pv.name)}, ${esc(pv.cred)}</label>`).join("")}</div><span class="hint">${cset(fc,"resultsScope")==="provider"?"This clinic limits results by provider: linked users see only these providers' orders. Leave all unticked for staff who should see everything.":"This clinic lets every user see all results, so links are for reference only."}</span></div>`:""}`}
 ${!f.id?`<p class="xs muted" style="margin-top:16px">You'll get a temporary password to give them. They choose their own password the first time they sign in; lab staff also set up two-step verification.</p>`:""}`}
function userFormModal(){modal(uf.id?`Edit ${uf.name||uf.email}`:"Add user",userForm(),{foot:`<button class="btn" data-a="closeModal">Cancel</button><button class="btn primary" data-a="saveUser" ${uf.busy?"disabled":""}>${uf.busy?"Saving…":uf.id?"Save changes":"Create user"}</button>`})}
function showTempPw(name,pw){modal("Temporary password",`<p>Give this to <b>${esc(name)}</b> privately, in person or by phone. Don't send it by email.</p><div style="margin:16px 0;padding:14px;border-radius:10px;background:var(--sunken);font:600 20px/1.3 ui-monospace,Menlo,Consolas,monospace;letter-spacing:.06em;text-align:center;user-select:all">${esc(pw)}</div><p class="small muted">It works once. At first sign-in they'll choose their own password (lab staff also set up two-step verification). This is the only time it's shown.</p>`,{foot:`<button class="btn primary" data-a="closeModal">Done</button>`})}

/* ---------- audit log ---------- */
let lastDoc=null;
const AU={from:ymd(Date.now()-7*DAY,"-"),to:ymd(Date.now(),"-"),actor:"",action:"",q:"",rows:null,loading:false,more:false,profiles:null,err:""};
const AUDIT_ACTIONS=[["","All activity"],["view","Viewed"],["insert","Created"],["update","Changed"],["delete","Deleted"],["print","Printed"],["export","Exported"],["send","Alert sent"],["sign_in,sign_out","Sign-ins and sign-outs"]];
const ACT_LBL={reset_password:"Reset password",reset_mfa:"Reset two-step",view:"Viewed",insert:"Created",update:"Changed",delete:"Deleted",print:"Printed",export:"Exported",send:"Sent alert",sign_in:"Signed in",sign_out:"Signed out"};
const TBL_LBL={orders:"Order",patients:"Patient",clinics:"Clinic",claims:"Claim",settings:"Lab settings",profiles:"User access",session:"Portal",files:"File",manifests:"Manifest",outbox:"Alert"};
const FIELD_LBL={status:"status",results:"results",history:"activity",readAt:"read receipt",flags:"flags",confirm:"definitive tests",tests:"tests",meds:"medications",ins:"insurance",first:"first name",last:"last name",dob:"date of birth",notify:"alert settings",providers:"providers",lines:"claim lines",sentAt:"export time",batch:"export batch",scans:"requisition scans",sendout:"send-out",consents:"consents",releasedAt:"release time"};
function auditRecordIds(q){q=q.trim().toLowerCase();if(!q)return null;const ids=[];
 S.orders.forEach(o=>{const p=patientOf(o.patientId);if(`${o.accession} ${p?p.first+" "+p.last+" "+p.last+", "+p.first+" "+p.mrn:""}`.toLowerCase().includes(q))ids.push(o.id)});
 S.patients.forEach(p=>{if(`${p.first} ${p.last} ${p.last}, ${p.first} ${p.mrn}`.toLowerCase().includes(q))ids.push(p.id)});
 S.clinics.forEach(c=>{if(`${c.name} ${c.acct||""}`.toLowerCase().includes(q))ids.push(c.id)});
 S.claims.forEach(c=>{if(c.id.toLowerCase().includes(q))ids.push(c.id)});
 return ids}
function auditWho(id){if(!id)return "System or administrator";const u=AU.profiles&&AU.profiles[id];return u?(u.name||u.email):"Unknown user"}
function auditRecord(r){
 if(r.tbl==="orders"){const o=orderOf(r.row_id);if(o){const p=patientOf(o.patientId);return `<button class="link" data-a="openOrder" data-id="${o.id}">${o.accession}</button> <span class="muted">${esc(pname(p))}</span>`}}
 if(r.tbl==="patients"){const p=patientOf(r.row_id);if(p)return `<button class="link" data-a="openPatient" data-id="${p.id}">${esc(pname(p))}</button> <span class="muted">${esc(p.mrn)}</span>`}
 if(r.tbl==="clinics"){const c=clinicOf(r.row_id);if(c)return esc(c.name)}
 if(r.tbl==="profiles"){const u=AU.profiles&&AU.profiles[r.row_id];return esc(u?(u.name||u.email):(r.detail&&r.detail.email)||"User")}
 if(r.tbl==="session")return "Portal";
 return esc(r.row_id||"")}
function auditDetail(r){const d=r.detail||{};const out=[];
 if(d.what)out.push(d.what);
 if(d.status)out.push(`status ${d.status[0]||"new"} → ${d.status[1]}`);
 if(d.changed){const f=d.changed.filter(k=>k!=="status"&&k!=="history").map(k=>FIELD_LBL[k]||k);if(f.length)out.push(f.slice(0,6).join(", ")+(f.length>6?` +${f.length-6} more`:""))}
 if(r.tbl==="profiles")out.push(`${d.previousRole&&d.previousRole!==d.role?`${d.previousRole} → `:""}${d.role||""}${d.clinic?` · ${esc((clinicOf(d.clinic)||{}).name||d.clinic)}`:""}`);
 if(d.channel)out.push(`${d.channel.toLowerCase()} ${d.status?d.status.toLowerCase():""}`);
 if(d.reason)out.push(d.reason);
 return esc(out.filter(Boolean).join(" · "))}
async function loadAudit(more){if(AU.loading)return;AU.loading=true;AU.err="";if(!more)AU.rows=null;render();
 try{if(!AU.profiles){const ps=await DB.profilesAll();AU.profiles=Object.fromEntries(ps.map(p=>[p.user_id,p]))}
  const ids=auditRecordIds(AU.q);
  if(ids&&!ids.length){AU.rows=[];AU.more=false}
  else{const rows=await DB.audit({from:AU.from,to:AU.to,actor:AU.actor,action:AU.action,rowIds:ids,offset:more?(AU.rows||[]).length:0});AU.rows=more?[...(AU.rows||[]),...rows]:rows;AU.more=rows.length===200}}
 catch(e){AU.err=errMsg(e);AU.rows=AU.rows||[]}
 finally{AU.loading=false;render()}}
