Object.assign(A,{
 sendAlerts(){sendAlertsNow(true)},
 retryAlerts(){S.outbox.forEach(x=>{if(x.status==="Failed"){x.status="Queued";x.detail=""}});save();sendAlertsNow(true)},
 async login(){const ev=$("#le"),pv=$("#lp");if(ev)lf.email=ev.value;if(pv)lf.pw=pv.value;if(!lf.email.trim()||!lf.pw)return toast("Enter your email or username and password.");try{try{if(lf.trust)localStorage.setItem("fbg-trust",String(Date.now()+12*36e5));else localStorage.removeItem("fbg-trust")}catch(e){}await DB.signIn(loginEmail(lf.email),lf.pw);lf.pw="";await boot()}catch(e){toast(/invalid/i.test(errMsg(e))?"That email and password don't match an account.":/confirm/i.test(errMsg(e))?"Confirm your email first. Check your inbox for the link.":errMsg(e))}},
 async forgotPw(){const ev=$("#le");if(ev)lf.email=ev.value;const e=lf.email.trim();if(!e)return toast("Enter your email above first.");await DB.resetPassword(e);toast("If that email has an account, a reset link is on its way.")},
 async setNewPw(){if((lf.pw1||"").length<12)return toast("Use at least 12 characters.");if(lf.pw1!==lf.pw2)return toast("The passwords don't match.");try{await DB.updatePassword(lf.pw1);if(forcedPw){await DB.passwordChanged();forcedPw=false}lf.pw1=lf.pw2="";toast("Password updated");await boot()}catch(e){toast(errMsg(e))}},
 async mfaVerify(){const code=(lf.code||"").replace(/\s/g,"");if(!/^\d{6}$/.test(code))return toast("Enter the 6-digit code.");try{await DB.mfaVerify(mfa.factorId,code)}catch(e){return toast("That code didn't work. Wait for a new code and try again.")}lf.code="";mfa=null;await boot()},
 async logout(){if(S.offline){if(S.orders.length&&!confirm(`${S.orders.length} order${S.orders.length>1?"s haven't":" hasn't"} uploaded yet. They stay encrypted on this device and upload the next time you sign in here. Sign out?`))return;Offline.clearStoredSession();S=emptyS();draft=null;closeModal();route={v:"login",p:{}};render();return}try{if(me()){await DB.flushNow(S,isLab());DB.log("sign_out","session",S.session);await new Promise(r=>setTimeout(r,250))}}catch(e){}try{sessionStorage.removeItem("fbg-signed-in");localStorage.removeItem("fbg-trust")}catch(e){}await DB.signOut();S=emptyS();draft=null;cs=null;labForm=null;closeModal();route={v:"login",p:{}};render()},
 toLogin(){route={v:"login",p:{}};render()},
 theme(){const dark=document.documentElement.getAttribute("data-theme")==="dark"||(!S.theme&&matchMedia("(prefers-color-scheme: dark)").matches);S.theme=dark?"light":"dark";try{localStorage.setItem("fbg-theme",S.theme)}catch(e){}applyTheme()},
});

/* ---------- events ---------- */
document.addEventListener("click",ev=>{const el=ev.target.closest("[data-a]");if(!el)return;if(el.dataset.a==="bgClose"){if(ev.target===el)closeModal();return}const fn=A[el.dataset.a];if(!fn)return;if(el.tagName!=="INPUT")ev.preventDefault();fn(el,ev)});
function setPath(b,val){const parts=b.split(".");const r=parts.shift();
 if(r==="cmap"){const[si,ai,ki,f]=parts;const sp=SPECS[+si];const it=((S.confMap[sp]||{})[defList(sp)[+ai]]||[])[+ki];if(it){it[f]=val;save()}return}
 if(r==="fees"){S.fees[parts[0]]=val;save();return}
 if(r==="avc"){const c=avCfg();S.lab.autoVerify={...c,[parts[0]]:isFinite(parseFloat(val))?parseFloat(val):val};save();return}
 if(r==="res"){const o=S.orders.find(x=>x.id===resEdit._id);const[code,idx,field]=parts;const a=analytesFor(o,T(code))[+idx];if(!a)return;resEdit[code]=resEdit[code]||{};resEdit[code][a.name]=resEdit[code][a.name]||{};const cur=resEdit[code][a.name];if(field==="k")manualConc(o,code,a,cur,+parts[3],val);else{cur[field]=val;manualDerive(o,code,a,cur,field)}return}let o=roots[r]&&roots[r]();if(!o)return;
 // result keys may contain dots? analyte names don't; codes don't.
 for(let i=0;i<parts.length-1;i++){if(o[parts[i]]==null)o[parts[i]]={};o=o[parts[i]]}o[parts[parts.length-1]]=val}
function onInput(ev){const t=ev.target,b=t.dataset&&t.dataset.b;if(!b)return;setPath(b,t.type==="checkbox"?t.checked:t.value);
 if(b==="ui.gq"){render();return}
 if(t.dataset.live){if(ev.type==="input"&&t.tagName==="SELECT")return;render()}}
document.addEventListener("input",onInput);
document.addEventListener("change",ev=>{const t=ev.target;if(t.type==="file"&&t.dataset.qfile){const f=t.files&&t.files[0],k=t.dataset.qfile;t.value="";if(!f||!qmf)return;if(f.size>20*1024*1024)return toast("Files must be under 20 MB.");toast("Uploading…");DB.qmsUpload(f).then(r=>{qmf[k]=r;qFormModal();toast("Uploaded")}).catch(e=>toast("Upload failed: "+errMsg(e)));return}if(t.type==="file"&&t.dataset.reqscan){const fs=[...(t.files||[])];t.value="";if(!draft)return;Promise.all(fs.map(f=>compressImage(f,1700,.72))).then(us=>{draft.scans.push(...us);render()}).catch(()=>toast("That file couldn't be read as an image."));return}if(t.type==="file"&&t.dataset.card){const f=t.files&&t.files[0],k=t.dataset.card;t.value="";if(!f||!ptForm)return;compressImage(f).then(u=>{ptForm.ins[k]=u;render()}).catch(()=>toast("That file couldn't be read as an image."));return}if(t.type==="file"&&t.dataset.imp){const f=t.files&&t.files[0],kind=t.dataset.imp;t.value="";if(!f)return;if(/\.xlsx$/i.test(f.name)){readXlsxFile(f).then(res=>{const rows=Array.isArray(res[0]&&res[0].data)?res[0].data:res;runImport(kind,rows.map(r=>r.map(c=>c==null?"":c instanceof Date?c.toISOString().slice(0,19):String(c).replace(/[\t\r\n]/g," ")).join("\t")).join("\n"))}).catch(()=>toast("That Excel file couldn't be read. Save it as CSV and try again."))}else f.text().then(txt=>runImport(kind,txt));return}if(t.tagName==="SELECT"||t.type==="checkbox"||t.type==="date"){if(t.dataset.b){setPath(t.dataset.b,t.type==="checkbox"?t.checked:t.value);if(t.dataset.live)render()}}});
document.addEventListener("submit",ev=>{ev.preventDefault();if(ev.target&&ev.target.id==="loginForm")A.login()});
document.addEventListener("keydown",ev=>{if(ev.key==="Escape"&&$("#modal-root").innerHTML)closeModal();if(ev.key==="Enter"&&ev.target.dataset&&ev.target.dataset.enter){ev.preventDefault();A[ev.target.dataset.enter]()}});

function after(){initSigs();drawMolecule();if(me()&&isLab())setTimeout(avSweep,50)}
function drawMolecule(){const cv=$("#molecule");if(!cv||!cv.getContext)return;const r=cv.getBoundingClientRect(),dpr=window.devicePixelRatio||1;cv.width=r.width*dpr;cv.height=r.height*dpr;const x=cv.getContext("2d");if(!x)return;x.scale(dpr,dpr);
 const cx=r.width*.62,cy=r.height*.34,R=Math.min(r.width,r.height)*.3;let seed=7;const rnd=()=>(seed=(seed*16807)%2147483647)/2147483647;
 const pts=[];for(let i=0;i<34;i++){const a=i/34*Math.PI*2+rnd()*.2,rr=R*(.55+rnd()*.5);pts.push([cx+Math.cos(a)*rr,cy+Math.sin(a)*rr,4+rnd()*11,a])}
 const col=a=>{const t=(Math.cos(a-2.4)+1)/2;const c1=[142,121,198],c2=[26,163,223];return `rgb(${c1.map((v,i)=>Math.round(v+(c2[i]-v)*(1-t))).join(",")})`};
 x.lineWidth=3;pts.forEach((p,i)=>{if(i%2===0){const q=pts[(i+1)%pts.length];x.strokeStyle=col(p[3]);x.globalAlpha=.8;x.beginPath();x.moveTo(p[0],p[1]);x.lineTo(q[0],q[1]);x.stroke()}});
 x.globalAlpha=1;pts.forEach(p=>{x.fillStyle=col(p[3]);x.beginPath();x.arc(p[0],p[1],p[2],0,7);x.fill()})}
window.addEventListener("resize",()=>{if($("#molecule"))drawMolecule()});

boot();
